INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (50,44,'Qaaf','يَوۡمَ تَشَقَّقُ ٱلۡأَرۡضُ عَنۡهُمۡ سِرَاعࣰ اۚ ذَٰلِكَ حَشۡرٌ عَلَيۡنَا يَسِيرࣱ‏','اس دن زمین ان پر سے پھٹ جائے گی اور وہ جھٹ پٹ نکل کھڑے ہوں گے۔ یہ جمع کرنا ہمیں آسان ہے','˹Beware of˺ the Day the earth will split open, letting them rush forth. That will be an easy gathering for Us','और हमारी ही तरफ फिर कर आना है जिस दिन ज़मीन (उनके ऊपर से) फट जाएगी और ये झट पट निकल खड़े होंगे ये उठाना और जमा करना');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (50,45,'Qaaf','نَّحۡنُ أَعۡلَمُ بِمَا يَقُولُونَۖ وَمَآ أَنتَ عَلَيۡهِم بِجَبَّارࣲۖ فَذَكِّرۡ بِٱلۡقُرۡءَانِ مَن يَخَافُ وَعِيدِ','یہ لوگ جو کچھ کہتے ہیں ہمیں خوب معلوم ہے اور تم ان پر زبردستی کرنے والے نہیں ہو۔ پس جو ہمارے (عذاب کی) وعید سے ڈرے اس کو قرآن سے نصیحت کرتے رہو','We know best what they say. And you ˹O Prophet˺ are not ˹there˺ to compel them ˹to believe˺. So remind with the Quran ˹only˺ those who fear My warning','और हम पर बहुत आसान है (ऐ रसूल) ये लोग जो कुछ कहते हैं हम (उसे) ख़ूब जानते हैं और तुम उन पर जब्र तो देते नहीं हो तो जो हमारे (अज़ाब के) वायदे से डरे उसको तुम क़ुरान के ज़रिए नसीहत करते रहो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (51,1,'Adh-Dhaariyat','وَٱلذَّٰرِيَٰتِ ذَرۡوࣰ ا','بکھیرنے والیوں کی قسم جو اُڑا کر بکھیر دیتی ہیں','By the winds scattering ˹dust˺','उन (हवाओं की क़सम) जो (बादलों को) उड़ा कर तितर बितर कर देती हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (51,2,'Adh-Dhaariyat','فَٱلۡحَٰمِلَٰتِ وِقۡرࣰ ا','پھر (پانی کا) بوجھ اٹھاتی ہیں','and ˹the clouds˺ loaded with rain','फिर (पानी का) बोझ उठाती हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (51,3,'Adh-Dhaariyat','فَٱلۡجَٰرِيَٰتِ يُسۡرࣰ ا','پھر آہستہ آہستہ چلتی ہیں','and ˹the ships˺ gliding with ease','फिर आहिस्ता आहिस्ता चलती हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (51,4,'Adh-Dhaariyat','فَٱلۡمُقَسِّمَٰتِ أَمۡرًا','پھر چیزیں تقسیم کرتی ہیں','and ˹the angels˺ administering affairs by ˹Allah’s˺ command','फिर एक ज़रूरी चीज़ (बारिश) को तक़सीम करती हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (51,5,'Adh-Dhaariyat','إِنَّمَا تُوعَدُونَ لَصَادِقࣱ‏','کہ جس چیز کا تم سے وعدہ کیا جاتا ہے وہ سچا ہے','Indeed, what you are promised is true','कि तुम से जो वायदा किया जाता है ज़रूर बिल्कुल सच्चा है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (51,6,'Adh-Dhaariyat','وَإِنَّ ٱلدِّينَ لَوَٰقِعࣱ‏','اور انصاف (کا دن) ضرور واقع ہوگا','And the Judgment will certainly come to pass','और (आमाल की) जज़ा (सज़ा) ज़रूर होगी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (51,7,'Adh-Dhaariyat','وَٱلسَّمَآءِ ذَاتِ ٱلۡحُبُكِ','اور آسمان کی قسم جس میں رسے ہیں','˹And˺ by the heavens in their marvellous design','और आसमान की क़सम जिसमें रहते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (51,8,'Adh-Dhaariyat','إِنَّكُمۡ لَفِي قَوۡلࣲ مُّخۡتَلِفࣲ‏','کہ (اے اہل مکہ) تم ایک متناقض بات میں (پڑے ہوئے) ہو','Surely you are ˹lost˺ in conflicting views ˹regarding the truth˺','कि (ऐ अहले मक्का) तुम लोग एक ऐसी मुख्तलिफ़ बेजोड़ बात में पड़े हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (51,9,'Adh-Dhaariyat','يُؤۡفَكُ عَنۡهُ مَنۡ أُفِكَ','اس سے وہی پھرتا ہے جو (خدا کی طرف سے) پھیرا جائے','Only those ˹destined to be˺ deluded are turned away from it','कि उससे वही फेरा जाएगा (गुमराह होगा)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (51,10,'Adh-Dhaariyat','قُتِلَ ٱلۡخَرَّٰصُونَ','اٹکل دوڑانے والے ہلاک ہوں','Condemned are the liars—','जो (ख़ुदा के इल्म में) फेरा जा चुका है अटकल दौड़ाने वाले हलाक हों');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (51,11,'Adh-Dhaariyat','ٱلَّذِينَ هُمۡ فِي غَمۡرَةࣲ سَاهُونَ','جو بےخبری میں بھولے ہوئے ہیں','those who are ˹steeped˺ in ignorance, totally heedless','जो ग़फलत में भूले हुए (पड़े) हैं पूछते हैं कि जज़ा का दिन कब होगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (51,12,'Adh-Dhaariyat','يَسۡـَٔلُونَ أَيَّانَ يَوۡمُ ٱلدِّينِ','پوچھتے ہیں کہ جزا کا دن کب ہوگا؟','They ask ˹mockingly˺, “When is this Day of Judgment?”','उस दिन (होगा)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (51,13,'Adh-Dhaariyat','يَوۡمَ هُمۡ عَلَى ٱلنَّارِ يُفۡتَنُونَ','اُس دن (ہوگا) جب ان کو آگ میں عذاب دیا جائے گا','˹It is˺ the Day they will be tormented over the Fire','जब इनको (जहन्नुम की) आग में अज़ाब दिया जाएगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (51,14,'Adh-Dhaariyat','ذُوقُواْ فِتۡنَتَكُمۡ هَٰذَا ٱلَّذِي كُنتُم بِهِۦ تَسۡتَعۡجِلُونَ','اب اپنی شرارت کا مزہ چکھو۔ یہ وہی ہے جس کے لئے تم جلدی مچایا کرتے تھے','˹They will be told,˺ “Taste your torment! This is what you sought to hasten.”','(और उनसे कहा जाएगा) अपने अज़ाब का मज़ा चखो ये वही है जिसकी तुम जल्दी मचाया करते थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (51,15,'Adh-Dhaariyat','إِنَّ ٱلۡمُتَّقِينَ فِي جَنَّٰتࣲ وَعُيُونٍ','بےشک پرہیزگار بہشتوں اور چشموں میں (عیش کر رہے) ہوں گے','Indeed, the righteous will be amid Gardens and springs','बेशक परहेज़गार लोग (बेहिश्त के) बाग़ों और चश्मों में (ऐश करते) होगें');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (51,16,'Adh-Dhaariyat','ءَاخِذِينَ مَآ ءَاتَىٰهُمۡ رَبُّهُمۡۚ إِنَّهُمۡ كَانُواْ قَبۡلَ ذَٰلِكَ مُحۡسِنِينَ','(اور) جو جو (نعمتیں) ان کا پروردگار انہیں دیتا ہوگا ان کو لے رہے ہوں گے۔ بےشک وہ اس سے پہلے نیکیاں کرتے تھے','˹joyfully˺ receiving what their Lord will grant them. Before this ˹reward˺ they were truly good-doers ˹in the world˺','जो उनका परवरदिगार उन्हें अता करता है ये (ख़ुश ख़ुश) ले रहे हैं ये लोग इससे पहले (दुनिया में) नेको कार थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (51,17,'Adh-Dhaariyat','كَانُواْ قَلِيلࣰ ا مِّنَ ٱلَّيۡلِ مَا يَهۡجَعُونَ','رات کے تھوڑے سے حصے میں سوتے تھے','they used to sleep only little in the night','(इबादत की वजह से) रात को बहुत ही कम सोते थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (51,18,'Adh-Dhaariyat','وَبِٱلۡأَسۡحَارِ هُمۡ يَسۡتَغۡفِرُونَ','اور اوقات سحر میں بخشش مانگا کرتے تھے','and pray for forgiveness before dawn','और पिछले पहर को अपनी मग़फ़िरत की दुआएं करते थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (51,19,'Adh-Dhaariyat','وَفِيٓ أَمۡوَٰلِهِمۡ حَقࣱّ لِّلسَّآئِلِ وَٱلۡمَحۡرُومِ','اور ان کے مال میں مانگنے والے اور نہ مانگنے والے (دونوں) کا حق ہوتا تھا','And in their wealth there was a rightful share ˹fulfilled˺ for the beggar and the poor','और उनके माल में माँगने वाले और न माँगने वाले (दोनों) का हिस्सा था');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (51,20,'Adh-Dhaariyat','وَفِي ٱلۡأَرۡضِ ءَايَٰتࣱ لِّلۡمُوقِنِينَ','اور یقین کرنے والوں کے لئے زمین میں (بہت سی) نشانیاں ہیں','There are ˹countless˺ signs on earth for those with sure faith','और यक़ीन करने वालों के लिए ज़मीन में (क़ुदरते ख़ुदा की) बहुत सी निशानियाँ हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (51,21,'Adh-Dhaariyat','وَفِيٓ أَنفُسِكُمۡۚ أَفَلَا تُبۡصِرُونَ','اور خود تمہارے نفوس میں تو کیا تم دیکھتے نہیں؟','as there are within yourselves. Can you not see','और ख़ुदा तुम में भी हैं तो क्या तुम देखते नहीं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (51,22,'Adh-Dhaariyat','وَفِي ٱلسَّمَآءِ رِزۡقُكُمۡ وَمَا تُوعَدُونَ','اور تمہارا رزق اور جس چیز کا تم سے وعدہ کیا جاتا ہے آسمان میں ہے','In heaven is your sustenance and whatever you are promised','और तुम्हारी रोज़ी और जिस चीज़ का तुमसे वायदा किया जाता है आसमान में है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (51,23,'Adh-Dhaariyat','فَوَرَبِّ ٱلسَّمَآءِ وَٱلۡأَرۡضِ إِنَّهُۥ لَحَقࣱّ مِّثۡلَ مَآ أَنَّكُمۡ تَنطِقُونَ','تو آسمانوں اور زمین کے مالک کی قسم! یہ (اسی طرح) قابل یقین ہے جس طرح تم بات کرتے ہو','Then by the Lord of heaven and earth! ˹All˺ this is certainly as true as ˹the fact that˺ you can speak','तो आसमान व ज़मीन के मालिक की क़सम ये (क़ुरान) बिल्कुल ठीक है जिस तरह तुम बातें करते हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (51,24,'Adh-Dhaariyat','هَلۡ أَتَىٰكَ حَدِيثُ ضَيۡفِ إِبۡرَٰهِيمَ ٱلۡمُكۡرَمِينَ','بھلا تمہارے پاس ابراہیمؑ کے معزز مہمانوں کی خبر پہنچی ہے؟','Has the story of Abraham’s honoured guests reached you ˹O Prophet˺','क्या तुम्हारे पास इबराहीम के मुअज़िज़ मेहमानो (फ़रिश्तों) की भी ख़बर पहुँची है कि जब वह लोग उनके पास आए');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (51,25,'Adh-Dhaariyat','إِذۡ دَخَلُواْ عَلَيۡهِ فَقَالُواْ سَلَٰمࣰ اۖ قَالَ سَلَٰمࣱ قَوۡمࣱ مُّنكَرُونَ','جب وہ ان کے پاس آئے تو سلام کہا۔ انہوں نے بھی (جواب میں) سلام کہا (دیکھا تو) ایسے لوگ کہ نہ جان نہ پہچان','˹Remember˺ when they entered his presence and greeted ˹him with˺, “Peace!” He replied, “Peace ˹be upon you˺!” ˹Then he said to himself,˺ “˹These are˺ an unfamiliar people.”','तो कहने लगे (सलामुन अलैकुम) तो इबराहीम ने भी (अलैकुम) सलाम किया (देखा तो) ऐसे लोग जिनसे न जान न पहचान');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (51,26,'Adh-Dhaariyat','فَرَاغَ إِلَىٰٓ أَهۡلِهِۦ فَجَآءَ بِعِجۡلࣲ سَمِينࣲ‏','تو اپنے گھر جا کر ایک (بھنا ہوا) موٹا بچھڑا لائے','Then he slipped off to his family and brought a fat ˹roasted˺ calf','फिर अपने घर जाकर जल्दी से (भुना हुआ) एक मोटा ताज़ा बछड़ा ले आए');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (51,27,'Adh-Dhaariyat','فَقَرَّبَهُۥٓ إِلَيۡهِمۡ قَالَ أَلَا تَأۡكُلُونَ','(اور کھانے کے لئے) ان کے آگے رکھ دیا۔ کہنے لگے کہ آپ تناول کیوں نہیں کرتے؟','and placed it before them, asking, “Will you not eat?”','और उसे उनके आगे रख दिया (फिर) कहने लगे आप लोग तनाउल क्यों नहीं करते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (51,28,'Adh-Dhaariyat','فَأَوۡجَسَ مِنۡهُمۡ خِيفَةࣰۖ قَالُواْ لَا تَخَفۡۖ وَبَشَّرُوهُ بِغُلَٰمٍ عَلِيمࣲ‏','اور دل میں ان سے خوف معلوم کیا۔ (انہوں نے) کہا کہ خوف نہ کیجیئے۔ اور ان کو ایک دانشمند لڑکے کی بشارت بھی سنائی','˹They did not eat,˺ so he grew fearful of them. They reassured ˹him˺, “Do not be afraid,” and gave him good news of a knowledgeable son','(इस पर भी न खाया) तो इबराहीम उनसे जो ही जी में डरे वह लोग बोले आप अन्देशा न करें और उनको एक दानिशमन्द लड़के की ख़ुशख़बरी दी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (51,29,'Adh-Dhaariyat','فَأَقۡبَلَتِ ٱمۡرَأَتُهُۥ فِي صَرَّةࣲ فَصَكَّتۡ وَجۡهَهَا وَقَالَتۡ عَجُوزٌ عَقِيمࣱ‏','تو ابراہیمؑ کی بیوی چلاّتی آئی اور اپنا منہ پیٹ کر کہنے لگی کہ (اے ہے ایک تو) بڑھیا اور (دوسرے) بانجھ','Then his wife came forward with a cry, clasping her forehead ˹in astonishment˺, exclaiming, “˹A baby from˺ a barren, old woman!”','तो (ये सुनते ही) इबराहीम की बीवी (सारा) चिल्लाती हुई उनके सामने आयीं और अपना मुँह पीट लिया कहने लगीं (ऐ है) एक तो (मैं) बुढ़िया (उस पर) बांझ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (51,30,'Adh-Dhaariyat','قَالُواْ كَذَٰلِكِ قَالَ رَبُّكِۖ إِنَّهُۥ هُوَ ٱلۡحَكِيمُ ٱلۡعَلِيمُ','(انہوں نے) کہا (ہاں) تمہارے پروردگار نے یوں ہی فرمایا ہے۔ وہ بےشک صاحبِ حکمت (اور) خبردار ہے','They replied, “Such has your Lord decreed. He is truly the All-Wise, All-Knowing.”','लड़का क्यों कर होगा फ़रिश्ते बोले तुम्हारे परवरदिगार ने यूँ ही फरमाया है वह बेशक हिकमत वाला वाक़िफ़कार है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (51,31,'Adh-Dhaariyat','۞قَالَ فَمَا خَطۡبُكُمۡ أَيُّهَا ٱلۡمُرۡسَلُونَ','ابراہیمؑ نے کہا کہ فرشتو! تمہارا مدعا کیا ہے؟','˹Later,˺ Abraham asked, “What is your mission, O messengers?”','तब इबराहीम ने पूछा कि (ऐ ख़ुदा के) भेजे हुए फरिश्तों आख़िर तुम्हें क्या मुहिम दर पेश है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (51,32,'Adh-Dhaariyat','قَالُوٓاْ إِنَّآ أُرۡسِلۡنَآ إِلَىٰ قَوۡمࣲ مُّجۡرِمِينَ','انہوں نے کہا کہ ہم گنہگار لوگوں کی طرف بھیجے گئے ہیں','They replied, “We have actually been sent to a wicked people','वह बोले हम तो गुनाहगारों (क़ौमे लूत) की तरफ भेजे गए हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (51,33,'Adh-Dhaariyat','لِنُرۡسِلَ عَلَيۡهِمۡ حِجَارَةࣰ مِّن طِينࣲ‏','تاکہ ان پر کھنگر برسائیں','to send upon them stones of ˹baked˺ clay','ताकि उन पर मिटटी के पथरीले खरन्जे बरसाएँ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (51,34,'Adh-Dhaariyat','مُّسَوَّمَةً عِندَ رَبِّكَ لِلۡمُسۡرِفِينَ','جن پر حد سے بڑھ جانے والوں کے لئے تمہارے پروردگار کے ہاں سے نشان کردیئے گئے ہیں','marked by your Lord for the transgressors.”','जिन पर हद से बढ़ जाने वालों के लिए तुम्हारे परवरदिगार की तरफ से निशान लगा दिए गए हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (51,35,'Adh-Dhaariyat','فَأَخۡرَجۡنَا مَن كَانَ فِيهَا مِنَ ٱلۡمُؤۡمِنِينَ','تو وہاں جتنے مومن تھے ان کو ہم نے نکال لیا','Then ˹before the torment˺ We evacuated the believers from the city','ग़रज़ वहाँ जितने लोग मोमिनीन थे उनको हमने निकाल दिया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (51,36,'Adh-Dhaariyat','فَمَا وَجَدۡنَا فِيهَا غَيۡرَ بَيۡتࣲ مِّنَ ٱلۡمُسۡلِمِينَ','اور اس میں ایک گھر کے سوا مسلمانوں کا کوئی گھر نہ پایا','But We only found one family that had submitted ˹to Allah˺','और वहाँ तो हमने एक के सिवा मुसलमानों का कोई घर पाया भी नहीं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (51,37,'Adh-Dhaariyat','وَتَرَكۡنَا فِيهَآ ءَايَةࣰ لِّلَّذِينَ يَخَافُونَ ٱلۡعَذَابَ ٱلۡأَلِيمَ','اور جو لوگ عذاب الیم سے ڈرتے ہیں ان کے لئے وہاں نشانی چھوڑ دی','And We have left a sign there ˹as a lesson˺ for those who fear the painful punishment','और जो लोग दर्दनाक अज़ाब से डरते हैं उनके लिए वहाँ (इबरत की) निशानी छोड़ दी और मूसा (के हाल) में भी (निशानी है)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (51,38,'Adh-Dhaariyat','وَفِي مُوسَىٰٓ إِذۡ أَرۡسَلۡنَٰهُ إِلَىٰ فِرۡعَوۡنَ بِسُلۡطَٰنࣲ مُّبِينࣲ‏','اور موسیٰ (کے حال) میں (بھی نشانی ہے) جب ہم نے ان کو فرعون کی طرف کھلا ہوا معجزہ دے کر بھیجا','And in ˹the story of˺ Moses ˹was another lesson,˺ when We sent him to Pharaoh with compelling proof','जब हमने उनको फिरऔन के पास खुला हुआ मौजिज़ा देकर भेजा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (51,39,'Adh-Dhaariyat','فَتَوَلَّىٰ بِرُكۡنِهِۦ وَقَالَ سَٰحِرٌ أَوۡ مَجۡنُونࣱ‏','تو اس نے اپنی جماعت (کے گھمنڈ) پر منہ موڑ لیا اور کہنے لگا یہ تو جادوگر ہے یا دیوانہ','but Pharaoh was carried away by his power, saying ˹of Moses˺, “A magician or a madman!”','तो उसने अपने लशकर के बिरते पर मुँह मोड़ लिया और कहने लगा ये तो (अच्छा ख़ासा) जादूगर या सौदाई है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (51,40,'Adh-Dhaariyat','فَأَخَذۡنَٰهُ وَجُنُودَهُۥ فَنَبَذۡنَٰهُمۡ فِي ٱلۡيَمِّ وَهُوَ مُلِيمࣱ‏','تو ہم نے اس کو اور اس کے لشکروں کو پکڑ لیا اور ان کو دریا میں پھینک دیا اور وہ کام ہی قابل ملامت کرتا تھا','So We seized him and his soldiers, casting them into the sea while he was blameworthy','तो हमने उसको और उसके लशकर को ले डाला फिर उन सबको दरिया में पटक दिया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (51,41,'Adh-Dhaariyat','وَفِي عَادٍ إِذۡ أَرۡسَلۡنَا عَلَيۡهِمُ ٱلرِّيحَ ٱلۡعَقِيمَ','اور عاد (کی قوم کے حال) میں بھی (نشانی ہے) جب ہم نے ان پر نامبارک ہوا چلائی','And in ˹the story of˺ ’Âd ˹was another lesson,˺ when We sent against them the devastating wind','और वह तो क़ाबिले मलामत काम करता ही था और आद की क़ौम (के हाल) में भी निशानी है हमने उन पर एक बे बरकत ऑंधी चलायी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (51,42,'Adh-Dhaariyat','مَا تَذَرُ مِن شَيۡءٍ أَتَتۡ عَلَيۡهِ إِلَّا جَعَلَتۡهُ كَٱلرَّمِيمِ','وہ جس چیز پر چلتی اس کو ریزہ ریزہ کئے بغیر نہ چھوڑتی','There was nothing it came upon that it did not reduce to ashes','कि जिस चीज़ पर चलती उसको बोसीदा हडडी की तरह रेज़ा रेज़ा किए बग़ैर न छोड़ती');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (51,43,'Adh-Dhaariyat','وَفِي ثَمُودَ إِذۡ قِيلَ لَهُمۡ تَمَتَّعُواْ حَتَّىٰ حِينࣲ‏','اور (قوم) ثمود (کے حال) میں (نشانی ہے) جب ان سے کہا گیا کہ ایک وقت تک فائدہ اٹھالو','And in ˹the story of˺ Thamûd ˹was another lesson,˺ when they were told, “Enjoy yourselves ˹only˺ for a ˹short˺ while.”','और समूद (के हाल) में भी (क़ुदरत की निशानी) है जब उससे कहा गया कि एक ख़ास वक्त तक ख़ूब चैन कर लो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (51,44,'Adh-Dhaariyat','فَعَتَوۡاْ عَنۡ أَمۡرِ رَبِّهِمۡ فَأَخَذَتۡهُمُ ٱلصَّٰعِقَةُ وَهُمۡ يَنظُرُونَ','تو انہوں نے اپنے پروردگار کے حکم سے سرکشی کی۔ سو ان کو کڑک نے آ پکڑا اور وہ دیکھ رہے تھے','Still they persisted in defying the commands of their Lord, so they were overtaken by a ˹mighty˺ blast while they were looking on','तो उन्होने अपने परवरदिगार के हुक्म से सरकशी की तो उन्हें एक रोज़ कड़क और बिजली ने ले डाला और देखते ही रह गए');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (51,45,'Adh-Dhaariyat','فَمَا ٱسۡتَطَٰعُواْ مِن قِيَامࣲ وَمَا كَانُواْ مُنتَصِرِينَ','پھر وہ نہ تو اُٹھنے کی طاقت رکھتے تھے اور نہ مقابلہ ہی کرسکتے تھے','Then they were not able to rise up, nor were they helped','फिर न वह उठने की ताक़त रखते थे और न बदला ही ले सकते थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (51,46,'Adh-Dhaariyat','وَقَوۡمَ نُوحࣲ مِّن قَبۡلُۖ إِنَّهُمۡ كَانُواْ قَوۡمࣰ ا فَٰسِقِينَ','اور اس سے پہلے (ہم) نوح کی قوم کو (ہلاک کرچکے تھے) بےشک وہ نافرمان لوگ تھے','And the people of Noah ˹had also been destroyed˺ earlier. They were truly a rebellious people','और (उनसे) पहले (हम) नूह की क़ौम को (हलाक कर चुके थे) बेशक वह बदकार लोग थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (51,47,'Adh-Dhaariyat','وَٱلسَّمَآءَ بَنَيۡنَٰهَا بِأَيۡيْدࣲ وَإِنَّا لَمُوسِعُونَ','اور آسمانوں کو ہم ہی نے ہاتھوں سے بنایا اور ہم کو سب مقدور ہے','We built the universe with ˹great˺ might, and We are certainly expanding ˹it˺','और हमने आसमानों को अपने बल बूते से बनाया और बेशक हममें सब क़ुदरत है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (51,48,'Adh-Dhaariyat','وَٱلۡأَرۡضَ فَرَشۡنَٰهَا فَنِعۡمَ ٱلۡمَٰهِدُونَ','اور زمین کو ہم ہی نے بچھایا تو (دیکھو) ہم کیا خوب بچھانے والے ہیں','As for the earth, We spread it out. How superbly did We smooth it out','और ज़मीन को भी हम ही ने बिछाया तो हम कैसे अच्छे बिछाने वाले हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (51,49,'Adh-Dhaariyat','وَمِن كُلِّ شَيۡءٍ خَلَقۡنَا زَوۡجَيۡنِ لَعَلَّكُمۡ تَذَكَّرُونَ','اور ہر چیز کی ہم نے دو قسمیں بنائیں تاکہ تم نصیحت پکڑو','And We created pairs of all things so perhaps you would be mindful','और हम ही ने हर चीज़ की दो दो क़िस्में बनायीं ताकि तुम लोग नसीहत हासिल करो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (51,50,'Adh-Dhaariyat','فَفِرُّوٓاْ إِلَى ٱللَّهِۖ إِنِّي لَكُم مِّنۡهُ نَذِيرࣱ مُّبِينࣱ‏','تو تم لوگ خدا کی طرف بھاگ چلو میں اس کی طرف سے تم کو صریح رستہ بتانے والا ہوں','So ˹proclaim, O Prophet˺: “Flee to Allah! I am truly sent by Him with a clear warning to you','तो ख़ुदा ही की तरफ़ भागो मैं तुमको यक़ीनन उसकी तरफ से खुल्लम खुल्ला डराने वाला हूँ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (51,51,'Adh-Dhaariyat','وَلَا تَجۡعَلُواْ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَۖ إِنِّي لَكُم مِّنۡهُ نَذِيرࣱ مُّبِينࣱ‏','اور خدا کے ساتھ کسی اَور کو معبود نہ بناؤ۔ میں اس کی طرف سے تم کو صریح رستہ بتانے والا ہوں','And do not set up another god with Allah. I am truly sent by Him with a clear warning to you.”','और ख़ुदा के साथ दूसरा माबूद न बनाओ मैं तुमको यक़ीनन उसकी तरफ से खुल्लम खुल्ला डराने वाला हूँ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (51,52,'Adh-Dhaariyat','كَذَٰلِكَ مَآ أَتَى ٱلَّذِينَ مِن قَبۡلِهِم مِّن رَّسُولٍ إِلَّا قَالُواْ سَاحِرٌ أَوۡ مَجۡنُونٌ','اسی طرح ان سے پہلے لوگوں کے پاس جو پیغمبر آتا وہ اس کو جادوگر یا دیوانہ کہتے','Similarly, no messenger came to those before them without being told: “A magician or a madman!”','इसी तरह उनसे पहले लोगों के पास जो पैग़म्बर आता तो वह उसको जादूगर कहते या सिड़ी दीवाना (बताते)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (51,53,'Adh-Dhaariyat','أَتَوَاصَوۡاْ بِهِۦۚ بَلۡ هُمۡ قَوۡمࣱ طَاغُونَ','کیا یہ کہ ایک دوسرے کو اسی بات کی وصیت کرتے آئے ہیں بلکہ یہ شریر لوگ ہیں','Have they passed this ˹cliché˺ down to one another? In fact, they have ˹all˺ been a transgressing people','ये लोग एक दूसरे को ऐसी बात की वसीयत करते आते हैं (नहीं) बल्कि ये लोग हैं ही सरकश');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (51,54,'Adh-Dhaariyat','فَتَوَلَّ عَنۡهُمۡ فَمَآ أَنتَ بِمَلُومࣲ‏','تو ان سے اعراض کرو۔ تم کو (ہماری) طرف سے ملامت نہ ہوگی','So ˹now˺ turn away from them ˹O Prophet˺, for you will not be blamed','तो (ऐ रसूल) तुम इनसे मुँह फेर लो तुम पर तो कुछ इल्ज़ाम नहीं है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (51,55,'Adh-Dhaariyat','وَذَكِّرۡ فَإِنَّ ٱلذِّكۡرَىٰ تَنفَعُ ٱلۡمُؤۡمِنِينَ','اور نصیحت کرتے رہو کہ نصیحت مومنوں کو نفع دیتی ہے','But ˹continue to˺ remind. For certainly reminders benefit the believers','और नसीहत किए जाओ क्योंकि नसीहत मोमिनीन को फायदा देती है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (51,56,'Adh-Dhaariyat','وَمَا خَلَقۡتُ ٱلۡجِنَّ وَٱلۡإِنسَ إِلَّا لِيَعۡبُدُونِ','اور میں نے جنوں اور انسانوں کو اس لئے پیدا کیا ہے کہ میری عبادت کریں','I did not create jinn and humans except to worship Me','और मैने जिनों और आदमियों को इसी ग़रज़ से पैदा किया कि वह मेरी इबादत करें');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (51,57,'Adh-Dhaariyat','مَآ أُرِيدُ مِنۡهُم مِّن رِّزۡقࣲ وَمَآ أُرِيدُ أَن يُطۡعِمُونِ','میں ان سے طالب رزق نہیں اور نہ یہ چاہتا ہوں کہ مجھے (کھانا) کھلائیں','I seek no provision from them, nor do I need them to feed Me','न तो मैं उनसे रोज़ी का तालिब हूँ और न ये चाहता हूँ कि मुझे खाना खिलाएँ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (51,58,'Adh-Dhaariyat','إِنَّ ٱللَّهَ هُوَ ٱلرَّزَّاقُ ذُو ٱلۡقُوَّةِ ٱلۡمَتِينُ','خدا ہی تو رزق دینے والا زور آور اور مضبوط ہے','Indeed, Allah ˹alone˺ is the Supreme Provider—Lord of all Power, Ever Mighty','ख़ुदा ख़ुद बड़ा रोज़ी देने वाला ज़ोरावर (और) ज़बरदस्त है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (51,59,'Adh-Dhaariyat','فَإِنَّ لِلَّذِينَ ظَلَمُواْ ذَنُوبࣰ ا مِّثۡلَ ذَنُوبِ أَصۡحَٰبِهِمۡ فَلَا يَسۡتَعۡجِلُونِ','کچھ شک نہیں کہ ان ظالموں کے لئے بھی (عذاب کی) نوبت مقرر ہے جس طرح ان کے ساتھیوں کی نوبت تھی تو ان کو مجھ سے (عذاب) جلدی نہیں طلب کرنا چاہیئے','The wrongdoers will certainly have a share ˹of the torment˺ like that of their predecessors. So do not let them ask Me to hasten ˹it˺','तो (इन) ज़ालिमों के वास्ते भी अज़ाब का कुछ हिस्सा है जिस तरह उनके साथियों के लिए हिस्सा था तो इनको हम से जल्दी न करनी चाहिए');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (51,60,'Adh-Dhaariyat','فَوَيۡلࣱ لِّلَّذِينَ كَفَرُواْ مِن يَوۡمِهِمُ ٱلَّذِي يُوعَدُونَ','جس دن کا ان کافروں سے وعدہ کیا جاتا ہے اس سے ان کے لئے خرابی ہے','Woe then to the disbelievers when they face their Day which they are warned of','तो जिस दिन का इन काफ़िरों से वायदा किया जाता है इससे इनके लिए ख़राबी है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (52,1,'At-Tur','وَٱلطُّورِ','(کوہ) طور کی قسم','By Mount Ṭûr','(कोहे) तूर की क़सम');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (52,2,'At-Tur','وَكِتَٰبࣲ مَّسۡطُورࣲ‏','اور کتاب کی جو لکھی ہوئی ہے','And by the Book written','और उसकी किताब (लौहे महफूज़) की');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (52,3,'At-Tur','فِي رَقࣲّ مَّنشُورࣲ‏','کشادہ اوراق میں','on open pages ˹for all to read˺','जो क़ुशादा औराक़ में लिखी हुई है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (52,4,'At-Tur','وَٱلۡبَيۡتِ ٱلۡمَعۡمُورِ','اور آباد گھر کی','And by the ˹Sacred˺ House frequently visited','और बैतुल मामूर की (जो काबा के सामने फरिश्तों का क़िब्ला है)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (52,5,'At-Tur','وَٱلسَّقۡفِ ٱلۡمَرۡفُوعِ','اور اونچی چھت کی','And by the canopy raised ˹high˺','और ऊँची छत (आसमान) की');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (52,6,'At-Tur','وَٱلۡبَحۡرِ ٱلۡمَسۡجُورِ','اور ابلتے ہوئے دریا کی','And by the seas set on fire','और जोश व ख़रोश वाले समन्दर की');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (52,7,'At-Tur','إِنَّ عَذَابَ رَبِّكَ لَوَٰقِعࣱ‏','کہ تمہارے پروردگار کا عذاب واقع ہو کر رہے گا','Indeed, the punishment of your Lord will come to pass—','कि तुम्हारे परवरदिगार का अज़ाब बेशक वाकेए होकर रहेगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (52,8,'At-Tur','مَّا لَهُۥ مِن دَافِعࣲ‏','(اور) اس کو کوئی روک نہیں سکے گا','none will avert it—','(और) इसका कोई रोकने वाला नहीं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (52,9,'At-Tur','يَوۡمَ تَمُورُ ٱلسَّمَآءُ مَوۡرࣰ ا','جس دن آسمان لرزنے لگا کپکپا کر','on the Day the heavens will be shaken violently','जिस दिन आसमान चक्कर खाने लगेगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (52,10,'At-Tur','وَتَسِيرُ ٱلۡجِبَالُ سَيۡرࣰ ا','اور پہاڑ اُڑنے لگے اون ہو کر','and the mountains will be blown away entirely','और पहाड़ उड़ने लगेंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (52,11,'At-Tur','فَوَيۡلࣱ يَوۡمَئِذࣲ لِّلۡمُكَذِّبِينَ','اس دن جھٹلانے والوں کے لئے خرابی ہے','Then woe on that Day to the deniers—','तो उस दिन झुठलाने वालों की ख़राबी है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (52,12,'At-Tur','ٱلَّذِينَ هُمۡ فِي خَوۡضࣲ يَلۡعَبُونَ','جو خوض (باطل) میں پڑے کھیل رہے ہیں','those who amuse themselves with falsehood','जो लोग बातिल में पड़े खेल रहे हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (52,13,'At-Tur','يَوۡمَ يُدَعُّونَ إِلَىٰ نَارِ جَهَنَّمَ دَعًّا','جس دن ان کو آتش جہنم کی طرف دھکیل دھکیل کر لے جائیں گے','˹It is˺ the Day they will be fiercely shoved into the Fire of Hell','जिस दिन जहन्नुम की आग की तरफ उनको ढकेल ढकेल ले जाएँगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (52,14,'At-Tur','هَٰذِهِ ٱلنَّارُ ٱلَّتِي كُنتُم بِهَا تُكَذِّبُونَ','یہی وہ جہنم ہے جس کو تم جھوٹ سمجھتے تھے','˹They will be told,˺ “This is the Fire which you used to deny','(और उनसे कहा जाएगा) यही वह जहन्नुम है जिसे तुम झुठलाया करते थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (52,15,'At-Tur','أَفَسِحۡرٌ هَٰذَآ أَمۡ أَنتُمۡ لَا تُبۡصِرُونَ','تو کیا یہ جادو ہے یا تم کو نظر ہی نہیں آتا','Is this magic, or do you not see','तो क्या ये जादू है या तुमको नज़र ही नहीं आता');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (52,16,'At-Tur','ٱصۡلَوۡهَا فَٱصۡبِرُوٓاْ أَوۡ لَا تَصۡبِرُواْ سَوَآءٌ عَلَيۡكُمۡۖ إِنَّمَا تُجۡزَوۡنَ مَا كُنتُمۡ تَعۡمَلُونَ','اس میں داخل ہوجاؤ اور صبر کرو یا نہ کرو تمہارے لئے یکساں ہے۔ جو کام تم کیا کرتے تھے (یہ) انہی کا تم کو بدلہ مل رہا ہے','Burn in it! It is the same whether you endure ˹it˺ patiently or not. You are only rewarded for what you used to do.”','इसी में घुसो फिर सब्र करो या बेसब्री करो (दोनों) तुम्हारे लिए यकसाँ हैं तुम्हें तो बस उन्हीं कामों का बदला मिलेगा जो तुम किया करते थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (52,17,'At-Tur','إِنَّ ٱلۡمُتَّقِينَ فِي جَنَّٰتࣲ وَنَعِيمࣲ‏','جو پرہیزگار ہیں وہ باغوں اور نعتموں میں ہوں گے','Indeed, the righteous will be in Gardens and bliss','बेशक परहेज़गार लोग बाग़ों और नेअमतों में होंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (52,18,'At-Tur','فَٰكِهِينَ بِمَآ ءَاتَىٰهُمۡ رَبُّهُمۡ وَوَقَىٰهُمۡ رَبُّهُمۡ عَذَابَ ٱلۡجَحِيمِ','جو کچھ ان کے پروردگار نے ان کو بخشا اس (کی وجہ) سے خوشحال۔ اور ان کے پروردگار نے ان کو دوزخ کے عذاب سے بچا لیا','enjoying whatever their Lord will have granted them. And their Lord will have protected them from the torment of the Hellfire','जो (जो नेअमतें) उनके परवरदिगार ने उन्हें दी हैं उनके मज़े ले रहे हैं और उनका परवरदिगार उन्हें दोज़ख़ के अज़ाब से बचाएगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (52,19,'At-Tur','كُلُواْ وَٱشۡرَبُواْ هَنِيٓـَٔۢا بِمَا كُنتُمۡ تَعۡمَلُونَ','اپنے اعمال کے صلے میں مزے سے کھاؤ اور پیو','˹They will be told,˺ “Eat and drink happily for what you used to do.”','जो जो कारगुज़ारियाँ तुम कर चुके हो उनके सिले में (आराम से) तख्तों पर जो बराबर बिछे हुए हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (52,20,'At-Tur','مُتَّكِـِٔينَ عَلَىٰ سُرُرࣲ مَّصۡفُوفَةࣲۖ وَزَوَّجۡنَٰهُم بِحُورٍ عِينࣲ‏','تختوں پر جو برابر برابر بچھے ہوئے ہیں تکیہ لگائے ہوئے اور بڑی بڑی آنکھوں والی حوروں سے ہم ان کا عقد کر دیں گے','They will be reclining on thrones, ˹neatly˺ lined up ˹facing each other˺. And We will pair them to maidens with gorgeous eyes','तकिए लगाकर ख़ूब मज़े से खाओ पियो और हम बड़ी बड़ी ऑंखों वाली हूर से उनका ब्याह रचाएँगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (52,21,'At-Tur','وَٱلَّذِينَ ءَامَنُواْ وَٱتَّبَعَتۡهُمۡ ذُرِّيَّتُهُم بِإِيمَٰنٍ أَلۡحَقۡنَا بِهِمۡ ذُرِّيَّتَهُمۡ وَمَآ أَلَتۡنَٰهُم مِّنۡ عَمَلِهِم مِّن شَيۡءࣲۚ كُلُّ ٱمۡرِيِٕۭ بِمَا كَسَبَ رَهِينࣱ‏','اور جو لوگ ایمان لائے اور ان کی اولاد بھی (راہ) ایمان میں ان کے پیچھے چلی۔ ہم ان کی اولاد کو بھی ان (کے درجے) تک پہنچا دیں گے اور ان کے اعمال میں سے کچھ کم نہ کریں گے۔ ہر شخص اپنے اعمال میں پھنسا ہوا ہے','As for those who believe and whose descendants follow them in faith, We will elevate their descendants to their rank, never discounting anything ˹of the reward˺ of their deeds. Every person will reap only what they sowed','और जिन लोगों ने ईमान क़ुबूल किया और उनकी औलाद ने भी ईमान में उनका साथ दिया तो हम उनकी औलाद को भी उनके दर्जे पहुँचा देंगे और हम उनकी कारगुज़ारियों में से कुछ भी कम न करेंगे हर शख़्श अपने आमाल के बदले में गिरवी है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (52,22,'At-Tur','وَأَمۡدَدۡنَٰهُم بِفَٰكِهَةࣲ وَلَحۡمࣲ مِّمَّا يَشۡتَهُونَ','اور جس طرح کے میوے اور گوشت کو ان کا جی چاہے گا ہم ان کو عطا کریں گے','And We will ˹continually˺ provide them with whatever fruit or meat they desire','और जिस क़िस्म के मेवे और गोश्त को उनका जी चाहेगा हम उन्हें बढ़ाकर अता करेंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (52,23,'At-Tur','يَتَنَٰزَعُونَ فِيهَا كَأۡسࣰ ا لَّا لَغۡوࣱ فِيهَا وَلَا تَأۡثِيمࣱ‏','وہاں وہ ایک دوسرے سے جام شراب جھپٹ لیا کریں گے جس (کے پینے) سے نہ ہذیان سرائی ہوگی نہ کوئی گناہ کی بات','They will pass around to each other a drink ˹of pure wine,˺ which leads to no idle talk or sinfulness','वहाँ एक दूसरे से शराब का जाम ले लिया करेंगे जिसमें न कोई बेहूदगी है और न गुनाह');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (52,24,'At-Tur','۞وَيَطُوفُ عَلَيۡهِمۡ غِلۡمَانࣱ لَّهُمۡ كَأَنَّهُمۡ لُؤۡلُؤࣱ مَّكۡنُونࣱ‏','اور نوجوان خدمت گار (جو ایسے ہوں گے) جیسے چھپائے ہوئے موتی ان کے آس پاس پھریں گے','And they will be waited on by their youthful servants like spotless pearls','(और ख़िदमत के लिए) नौजवान लड़के उनके आस पास चक्कर लगाया करेंगे वह (हुस्न व जमाल में) गोया एहतियात से रखे हुए मोती हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (52,25,'At-Tur','وَأَقۡبَلَ بَعۡضُهُمۡ عَلَىٰ بَعۡضࣲ يَتَسَآءَلُونَ','اور ایک دوسرے کی طرف رخ کرکے آپس میں گفتگو کریں گے','They will turn to one another inquisitively','और एक दूसरे की तरफ रूख़ करके (लुत्फ की) बातें करेंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (52,26,'At-Tur','قَالُوٓاْ إِنَّا كُنَّا قَبۡلُ فِيٓ أَهۡلِنَا مُشۡفِقِينَ','کہیں گے کہ اس سے پہلے ہم اپنے گھر میں (خدا سے) ڈرتے رہتے تھے','They will say, “Before ˹this reward˺ we used to be in awe ˹of Allah˺ in the midst of our people','(उनमें से कुछ) कहेंगे कि हम इससे पहले अपने घर में (ख़ुदा से बहुत) डरा करते थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (52,27,'At-Tur','فَمَنَّ ٱللَّهُ عَلَيۡنَا وَوَقَىٰنَا عَذَابَ ٱلسَّمُومِ','تو خدا نے ہم پر احسان فرمایا اور ہمیں لو کے عذاب سے بچا لیا','So Allah has graced us and protected us from the torment of ˹Hell’s˺ scorching heat','तो ख़ुदा ने हम पर बड़ा एहसान किया और हमको (जहन्नुम की) लौ के अज़ाब से बचा लिया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (52,28,'At-Tur','إِنَّا كُنَّا مِن قَبۡلُ نَدۡعُوهُۖ إِنَّهُۥ هُوَ ٱلۡبَرُّ ٱلرَّحِيمُ','اس سے پہلے ہم اس سے دعائیں کیا کرتے تھے۔ بےشک وہ احسان کرنے والا مہربان ہے','Indeed, we used to call upon Him ˹alone˺ before. He is truly the Most Kind, Most Merciful.”','इससे क़ब्ल हम उनसे दुआएँ किया करते थे बेशक वह एहसान करने वाला मेहरबान है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (52,29,'At-Tur','فَذَكِّرۡ فَمَآ أَنتَ بِنِعۡمَتِ رَبِّكَ بِكَاهِنࣲ وَلَا مَجۡنُونٍ','تو (اے پیغمبر) تم نصیحت کرتے رہو تم اپنے پروردگار کے فضل سے نہ تو کاہن ہو اور نہ دیوانے','So ˹continue to˺ remind ˹all, O Prophet˺. For you, by the grace of your Lord, are not a fortune-teller or a madman','तो (ऐ रसूल) तुम नसीहत किए जाओ तो तुम अपने परवरदिगार के फज़ल से न काहिन हो और न मजनून किया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (52,30,'At-Tur','أَمۡ يَقُولُونَ شَاعِرࣱ نَّتَرَبَّصُ بِهِۦ رَيۡبَ ٱلۡمَنُونِ','کیا کافر کہتے ہیں کہ یہ شاعر ہے (اور) ہم اس کے حق میں زمانے کے حوادث کا انتظار کر رہے ہیں','Or do they say, “˹He is˺ a poet, for whom we ˹eagerly˺ await an ill-fate!”','क्या (तुमको) ये लोग कहते हैं कि (ये) शायर हैं (और) हम तो उसके बारे में ज़माने के हवादिस का इन्तेज़ार कर रहे हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (52,31,'At-Tur','قُلۡ تَرَبَّصُواْ فَإِنِّي مَعَكُم مِّنَ ٱلۡمُتَرَبِّصِينَ','کہہ دو کہ انتظار کئے جاؤ میں بھی تمہارے ساتھ انتظار کرتا ہوں','Say, “Keep waiting! I too am waiting with you.”','तुम कह दो कि (अच्छा) तुम भी इन्तेज़ार करो मैं भी इन्तेज़ार करता हूँ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (52,32,'At-Tur','أَمۡ تَأۡمُرُهُمۡ أَحۡلَٰمُهُم بِهَٰذَآۚ أَمۡ هُمۡ قَوۡمࣱ طَاغُونَ','کیا ان کی عقلیں ان کو یہی سکھاتی ہیں۔ بلکہ یہ لوگ ہیں ہی شریر','Or do their ˹intelligent˺ minds prompt them to this ˹paradox˺? Or are they ˹just˺ a transgressing people','क्या उनकी अक्लें उन्हें ये (बातें) बताती हैं या ये लोग हैं ही सरकश');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (52,33,'At-Tur','أَمۡ يَقُولُونَ تَقَوَّلَهُۥۚ بَل لَّا يُؤۡمِنُونَ','کیا (کفار) کہتے ہیں کہ ان پیغمبر نے قرآن از خود بنا لیا ہے بات یہ ہے کہ یہ (خدا پر) ایمان نہیں رکھتے','Or do they say, “He made this ˹Quran˺ up!”? In fact, they have no faith','क्या ये लोग कहते हैं कि इसने क़ुरान ख़ुद गढ़ लिया है बात ये है कि ये लोग ईमान ही नहीं रखते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (52,34,'At-Tur','فَلۡيَأۡتُواْ بِحَدِيثࣲ مِّثۡلِهِۦٓ إِن كَانُواْ صَٰدِقِينَ','اگر یہ سچے ہیں تو ایسا کلام بنا تو لائیں','Let them then produce something like it, if what they say is true','तो अगर ये लोग सच्चे हैं तो ऐसा ही कलाम बना तो लाएँ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (52,35,'At-Tur','أَمۡ خُلِقُواْ مِنۡ غَيۡرِ شَيۡءٍ أَمۡ هُمُ ٱلۡخَٰلِقُونَ','کیا یہ کسی کے پیدا کئے بغیر ہی پیدا ہوگئے ہیں۔ یا یہ خود (اپنے تئیں) پیدا کرنے والے ہیں','Or were they created by nothing, or are they ˹their own˺ creators','क्या ये लोग किसी के (पैदा किये) बग़ैर ही पैदा हो गए हैं या यही लोग (मख़लूक़ात के) पैदा करने वाले हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (52,36,'At-Tur','أَمۡ خَلَقُواْ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَۚ بَل لَّا يُوقِنُونَ','یا انہوں نے آسمانوں اور زمین کو پیدا کیا ہے؟ (نہیں) بلکہ یہ یقین ہی نہیں رکھتے','Or did they create the heavens and the earth? In fact, they have no firm belief ˹in Allah˺','या इन्होने ही ने सारे आसमान व ज़मीन पैदा किए हैं (नहीं) बल्कि ये लोग यक़ीन ही नहीं रखते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (52,37,'At-Tur','أَمۡ عِندَهُمۡ خَزَآئِنُ رَبِّكَ أَمۡ هُمُ ٱلۡمُصَۜيۡطِرُونَ','کیا ان کے پاس تمہارے پروردگار کے خزانے ہیں۔ یا یہ (کہیں کے) داروغہ ہیں؟','Or do they possess the treasuries of your Lord, or are they in control ˹of everything˺','क्या तुम्हारे परवरदिगार के ख़ज़ाने इन्हीं के पास हैं या यही लोग हाकिम हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (52,38,'At-Tur','أَمۡ لَهُمۡ سُلَّمࣱ يَسۡتَمِعُونَ فِيهِۖ فَلۡيَأۡتِ مُسۡتَمِعُهُم بِسُلۡطَٰنࣲ مُّبِينٍ','یا ان کے پاس کوئی سیڑھی ہے جس پر (چڑھ کر آسمان سے باتیں) سن آتے ہیں۔ تو جو سن آتا ہے وہ صریح سند دکھائے','Or do they have a stairway, by which they eavesdrop ˹on the heavens˺? Then let those who do so bring a compelling proof','या उनके पास कोई सीढ़ी है जिस पर (चढ़ कर आसमान से) सुन आते हैं जो सुन आया करता हो तो वह कोई सरीही दलील पेश करे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (52,39,'At-Tur','أَمۡ لَهُ ٱلۡبَنَٰتُ وَلَكُمُ ٱلۡبَنُونَ','کیا خدا کی تو بیٹیاں اور تمہارے بیٹے','Or does He have daughters ˹as you claim˺, while you ˹prefer to˺ have sons','क्या ख़ुदा के लिए बेटियाँ हैं और तुम लोगों के लिए बेटे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (52,40,'At-Tur','أَمۡ تَسۡـَٔلُهُمۡ أَجۡرࣰ ا فَهُم مِّن مَّغۡرَمࣲ مُّثۡقَلُونَ','(اے پیغمبر) کیا تم ان سے صلہ مانگتے ہو کہ ان پر تاوان کا بوجھ پڑ رہا ہے','Or are you ˹O Prophet˺ asking them for a reward ˹for the message˺ so that they are overburdened by debt','या तुम उनसे (तबलीग़े रिसालत की) उजरत माँगते हो कि ये लोग कर्ज़ के बोझ से दबे जाते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (52,41,'At-Tur','أَمۡ عِندَهُمُ ٱلۡغَيۡبُ فَهُمۡ يَكۡتُبُونَ','یا ان کے پاس غیب (کا علم) ہے کہ وہ اسے لکھ لیتے ہیں','Or do they have access to ˹the Record in˺ the unseen, so they copy it ˹for all to see˺','या इन लोगों के पास ग़ैब (का इल्म) है कि वह लिख लेते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (52,42,'At-Tur','أَمۡ يُرِيدُونَ كَيۡدࣰ اۖ فَٱلَّذِينَ كَفَرُواْ هُمُ ٱلۡمَكِيدُونَ','کیا یہ کوئی داؤں کرنا چاہتے ہیں تو کافر تو خود داؤں میں آنے والے ہیں','Or do they intend to scheme ˹against the Prophet˺? Then it is the disbelievers who will fall victim to ˹their˺ schemes','या ये लोग कुछ दाँव चलाना चाहते हैं तो जो लोग काफ़िर हैं वह ख़ुद अपने दांव में फँसे हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (52,43,'At-Tur','أَمۡ لَهُمۡ إِلَٰهٌ غَيۡرُ ٱللَّهِۚ سُبۡحَٰنَ ٱللَّهِ عَمَّا يُشۡرِكُونَ','کیا خدا کے سوا ان کا کوئی اور معبود ہے؟ خدا ان کے شریک بنانے سے پاک ہے','Or do they have a god other than Allah? Glorified is Allah far above what they associate ˹with Him˺','या ख़ुदा के सिवा इनका कोई (दूसरा) माबूद है जिन चीज़ों को ये लोग (ख़ुदा का) शरीक बनाते हैं वह उससे पाक और पाक़ीज़ा है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (52,44,'At-Tur','وَإِن يَرَوۡاْ كِسۡفࣰ ا مِّنَ ٱلسَّمَآءِ سَاقِطࣰ ا يَقُولُواْ سَحَابࣱ مَّرۡكُومࣱ‏','اور اگر یہ آسمان سے (عذاب) کا کوئی ٹکڑا گرتا ہوا دیکھیں تو کہیں کہ یہ گاڑھا بادل ہے','If they were to see a ˹deadly˺ piece of the sky fall down ˹upon them˺, still they would say, “˹This is just˺ a pile of clouds.”','और अगर ये लोग आसमान से कोई अज़ाब (अज़ाब का) टुकड़ा गिरते हुए देखें तो बोल उठेंगे ये तो दलदार बादल है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (52,45,'At-Tur','فَذَرۡهُمۡ حَتَّىٰ يُلَٰقُواْ يَوۡمَهُمُ ٱلَّذِي فِيهِ يُصۡعَقُونَ','پس ان کو چھوڑ دو یہاں تک کہ وہ روز جس میں وہ بےہوش کردیئے جائیں گے، سامنے آجائے','So leave them until they face their Day in which they will be struck dead—','तो (ऐ रसूल) तुम इनको इनकी हालत पर छोड़ दो यहाँ तक कि वह जिसमें ये बेहोश हो जाएँगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (52,46,'At-Tur','يَوۡمَ لَا يُغۡنِي عَنۡهُمۡ كَيۡدُهُمۡ شَيۡـࣰٔ ا وَلَا هُمۡ يُنصَرُونَ','جس دن ان کا کوئی داؤں کچھ بھی کام نہ آئے اور نہ ان کو (کہیں سے) مدد ہی ملے','the Day their scheming will be of no benefit to them whatsoever, nor will they be helped','इनके सामने आ जाए जिस दिन न इनकी मक्कारी ही कुछ काम आएगी और न इनकी मदद ही की जाएगी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (52,47,'At-Tur','وَإِنَّ لِلَّذِينَ ظَلَمُواْ عَذَابࣰ ا دُونَ ذَٰلِكَ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ','اور ظالموں کے لئے اس کے سوا اور عذاب بھی ہے لیکن ان میں کے اکثر نہیں جانتے','Also, the wrongdoers will certainly have another torment before that ˹Day˺, but most of them do not know','और इसमें शक़ नहीं कि ज़ालिमों के लिए इसके अलावा और भी अज़ाब है मगर उनमें बहुतेरे नहीं जानते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (52,48,'At-Tur','وَٱصۡبِرۡ لِحُكۡمِ رَبِّكَ فَإِنَّكَ بِأَعۡيُنِنَاۖ وَسَبِّحۡ بِحَمۡدِ رَبِّكَ حِينَ تَقُومُ','اور تم اپنے پروردگار کے حکم کے انتظار میں صبر کئے رہو۔ تم تو ہماری آنکھوں کے سامنے ہو اور جب اُٹھا کرو تو اپنے پروردگار کی تعریف کے ساتھ تسبیح کیا کرو','So be patient with your Lord’s decree, for you are truly under Our ˹watchful˺ Eyes. And glorify the praises of your Lord when you rise','और (ऐ रसूल) तुम अपने परवरदिगार के हुक्म से इन्तेज़ार में सब्र किए रहो तो तुम बिल्कुल हमारी निगेहदाश्त में हो तो जब तुम उठा करो तो अपने परवरदिगार की हम्द की तस्बीह किया करो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (52,49,'At-Tur','وَمِنَ ٱلَّيۡلِ فَسَبِّحۡهُ وَإِدۡبَٰرَ ٱلنُّجُومِ','اور رات کے بعض اوقات میں بھی اور ستاروں کے غروب ہونے کے بعد بھی اس کی تنزیہ کیا کرو','And glorify Him during part of the night and at the fading of the stars','और कुछ रात को भी और सितारों के ग़ुरूब होने के बाद तस्बीह किया करो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (53,1,'An-Najm','وَٱلنَّجۡمِ إِذَا هَوَىٰ','تارے کی قسم جب غائب ہونے لگے','By the stars when they fade away','तारे की क़सम जब टूटा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (53,2,'An-Najm','مَا ضَلَّ صَاحِبُكُمۡ وَمَا غَوَىٰ','کہ تمہارے رفیق (محمدﷺ) نہ رستہ بھولے ہیں نہ بھٹکے ہیں','Your fellow man is neither misguided nor astray','कि तुम्हारे रफ़ीक़ (मोहम्मद) न गुमराह हुए और न बहके');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (53,3,'An-Najm','وَمَا يَنطِقُ عَنِ ٱلۡهَوَىٰٓ','اور نہ خواہش نفس سے منہ سے بات نکالتے ہیں','Nor does he speak of his own whims','और वह तो अपनी नफ़सियानी ख्वाहिश से कुछ भी नहीं कहते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (53,4,'An-Najm','إِنۡ هُوَ إِلَّا وَحۡيࣱ يُوحَىٰ','یہ (قرآن) تو حکم خدا ہے جو (ان کی طرف) بھیجا جاتا ہے','It is only a revelation sent down ˹to him˺','ये तो बस वही है जो भेजी जाती है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (53,5,'An-Najm','عَلَّمَهُۥ شَدِيدُ ٱلۡقُوَىٰ','ان کو نہایت قوت والے نے سکھایا','He has been taught by one ˹angel˺ of mighty power','इनको निहायत ताक़तवर (फ़रिश्ते जिबरील) ने तालीम दी है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (53,6,'An-Najm','ذُو مِرَّةࣲ فَٱسۡتَوَىٰ','(یعنی جبرائیل) طاقتور نے پھر وہ پورے نظر آئے','and great perfection, who once rose to ˹his˺ true form','जो बड़ा ज़बरदस्त है और जब ये (आसमान के) ऊँचे (मुशरक़ो) किनारे पर था तो वह अपनी (असली सूरत में) सीधा खड़ा हुआ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (53,7,'An-Najm','وَهُوَ بِٱلۡأُفُقِ ٱلۡأَعۡلَىٰ','اور وہ (آسمان کے) اونچے کنارے میں تھے','while on the highest point above the horizon','फिर करीब हो (और आगे) बढ़ा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (53,8,'An-Najm','ثُمَّ دَنَا فَتَدَلَّىٰ','پھر قریب ہوئے اوراَور آگے بڑھے','then he approached ˹the Prophet˺, coming so close','(फिर जिबरील व मोहम्मद में) दो कमान का फ़ासला रह गया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (53,9,'An-Najm','فَكَانَ قَابَ قَوۡسَيۡنِ أَوۡ أَدۡنَىٰ','تو دو کمان کے فاصلے پر یا اس سے بھی کم','that he was only two arms-lengths away or even less','बल्कि इससे भी क़रीब था');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (53,10,'An-Najm','فَأَوۡحَىٰٓ إِلَىٰ عَبۡدِهِۦ مَآ أَوۡحَىٰ','پھر خدا نے اپنے بندے کی طرف جو بھیجا سو بھیجا','Then Allah revealed to His servant what He revealed ˹through Gabriel˺','ख़ुदा ने अपने बन्दे की तरफ जो ''वही'' भेजी सो भेजी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (53,11,'An-Najm','مَا كَذَبَ ٱلۡفُؤَادُ مَا رَأَىٰٓ','جو کچھ انہوں نے دیکھا ان کے دل نے اس کو جھوٹ نہ مانا','The ˹Prophet’s˺ heart did not doubt what he saw','तो जो कुछ उन्होने देखा उनके दिल ने झूठ न जाना');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (53,12,'An-Najm','أَفَتُمَٰرُونَهُۥ عَلَىٰ مَا يَرَىٰ','کیا جو کچھ وہ دیکھتے ہیں تم اس میں ان سے جھگڑتے ہو؟','How can you ˹O pagans˺ then dispute with him regarding what he saw','तो क्या वह (रसूल) जो कुछ देखता है तुम लोग उसमें झगड़ते हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (53,13,'An-Najm','وَلَقَدۡ رَءَاهُ نَزۡلَةً أُخۡرَىٰ','اور انہوں نے اس کو ایک بار بھی دیکھا ہے','And he certainly saw that ˹angel descend˺ a second time','और उन्होने तो उस (जिबरील) को एक बार (शबे मेराज) और देखा है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (53,14,'An-Najm','عِندَ سِدۡرَةِ ٱلۡمُنتَهَىٰ','پرلی حد کی بیری کے پاس','at the Lote Tree of the most extreme limit ˹in the seventh heaven˺—','सिदरतुल मुनतहा के नज़दीक');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (53,15,'An-Najm','عِندَهَا جَنَّةُ ٱلۡمَأۡوَىٰٓ','اسی کے پاس رہنے کی جنت ہے','near which is the Garden of ˹Eternal˺ Residence—','उसी के पास तो रहने की बेहिश्त है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (53,16,'An-Najm','إِذۡ يَغۡشَى ٱلسِّدۡرَةَ مَا يَغۡشَىٰ','جب کہ اس بیری پر چھا رہا تھا جو چھا رہا تھا','while the Lote Tree was overwhelmed with ˹heavenly˺ splendours','जब छा रहा था सिदरा पर जो छा रहा था');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (53,17,'An-Najm','مَا زَاغَ ٱلۡبَصَرُ وَمَا طَغَىٰ','ان کی آنکھ نہ تو اور طرف مائل ہوئی اور نہ (حد سے) آگے بڑھی','The ˹Prophet’s˺ sight never wandered, nor did it overreach','(उस वक्त भी) उनकी ऑंख न तो और तरफ़ माएल हुई और न हद से आगे बढ़ी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (53,18,'An-Najm','لَقَدۡ رَأَىٰ مِنۡ ءَايَٰتِ رَبِّهِ ٱلۡكُبۡرَىٰٓ','انہوں نے اپنے پروردگار (کی قدرت) کی کتنی ہی بڑی بڑی نشانیاں دیکھیں','He certainly saw some of his Lord’s greatest signs','और उन्होने यक़ीनन अपने परवरदिगार (की क़ुदरत) की बड़ी बड़ी निशानियाँ देखीं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (53,19,'An-Najm','أَفَرَءَيۡتُمُ ٱللَّٰتَ وَٱلۡعُزَّىٰ','بھلا تم لوگوں نے لات اور عزیٰ کو دیکھا','Now, have you considered ˹the idols of˺ Lât and ’Uzza','तो भला तुम लोगों ने लात व उज्ज़ा और तीसरे पिछले मनात को देखा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (53,20,'An-Najm','وَمَنَوٰةَ ٱلثَّالِثَةَ ٱلۡأُخۡرَىٰٓ','اور تیسرے منات کو (کہ یہ بت کہیں خدا ہوسکتے ہیں)','and the third one, Manât, as well','भला ये ख़ुदा हो सकते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (53,21,'An-Najm','أَلَكُمُ ٱلذَّكَرُ وَلَهُ ٱلۡأُنثَىٰ','(مشرکو!) کیا تمہارے لئے تو بیٹے اور خدا کے لئے بیٹیاں','Do you ˹prefer to˺ have sons while ˹you attribute˺ to Him daughters','क्या तुम्हारे तो बेटे हैं और उसके लिए बेटियाँ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (53,22,'An-Najm','تِلۡكَ إِذࣰ ا قِسۡمَةࣱ ضِيزَىٰٓ','یہ تقسیم تو بہت بےانصافی کی ہے','Then this is ˹truly˺ a biased distribution','ये तो बहुत बेइन्साफ़ी की तक़सीम है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (53,23,'An-Najm','إِنۡ هِيَ إِلَّآ أَسۡمَآءࣱ سَمَّيۡتُمُوهَآ أَنتُمۡ وَءَابَآؤُكُم مَّآ أَنزَلَ ٱللَّهُ بِهَا مِن سُلۡطَٰنٍۚ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَمَا تَهۡوَى ٱلۡأَنفُسُۖ وَلَقَدۡ جَآءَهُم مِّن رَّبِّهِمُ ٱلۡهُدَىٰٓ','وہ تو صرف نام ہی نام ہیں جو تم نے اور تمہارے باپ دادا نے گھڑ لئے ہیں۔ خدا نے تو ان کی کوئی سند نازل نہیں کی۔ یہ لوگ محض ظن (فاسد) اور خواہشات نفس کے پیچھے چل رہے ہیں۔ حالانکہ ان کے پروردگار کی طرف سے ان کے پاس ہدایت آچکی ہے','These ˹idols˺ are mere names that you and your forefathers have made up—a practice Allah has never authorized. They follow nothing but ˹inherited˺ assumptions and whatever ˹their˺ souls desire, although ˹true˺ guidance has already come to them from their Lord','ये तो बस सिर्फ नाम ही नाम है जो तुमने और तुम्हारे बाप दादाओं ने गढ़ लिए हैं, ख़ुदा ने तो इसकी कोई सनद नाज़िल नहीं की ये लोग तो बस अटकल और अपनी नफ़सानी ख्वाहिश के पीछे चल रहे हैं हालॉकि उनके पास उनके परवरदिगार की तरफ से हिदायत भी आ चुकी है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (53,24,'An-Najm','أَمۡ لِلۡإِنسَٰنِ مَا تَمَنَّىٰ','کیا جس چیز کی انسان آرزو کرتا ہے وہ اسے ضرور ملتی ہے','Or should every person ˹simply˺ have whatever ˹intercessors˺ they desire','क्या जिस चीज़ की इन्सान तमन्ना करे वह उसे ज़रूर मिलती है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (53,25,'An-Najm','فَلِلَّهِ ٱلۡأٓخِرَةُ وَٱلۡأُولَىٰ','آخرت اور دنیا تو الله ہی کے ہاتھ میں ہے','In fact, to Allah ˹alone˺ belongs this world and the next','आख़ेरत और दुनिया तो ख़ास ख़ुदा ही के एख्तेयार में हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (53,26,'An-Najm','۞وَكَم مِّن مَّلَكࣲ فِي ٱلسَّمَٰوَٰتِ لَا تُغۡنِي شَفَٰعَتُهُمۡ شَيۡـًٔا إِلَّا مِنۢ بَعۡدِ أَن يَأۡذَنَ ٱللَّهُ لِمَن يَشَآءُ وَيَرۡضَىٰٓ','اور آسمانوں میں بہت سے فرشتے ہیں جن کی سفارش کچھ بھی فائدہ نہیں دیتی مگر اس وقت کہ خدا جس کے لئے چاہے اجازت بخشے اور (سفارش) پسند کرے','˹Imagine˺ how many ˹noble˺ angels are in the heavens! ˹Even˺ their intercession would be of no benefit whatsoever, until Allah gives permission to whoever He wills and ˹only for the people He˺ approves','और आसमानों में बहुत से फरिश्ते हैं जिनकी सिफ़ारिश कुछ भी काम न आती, मगर ख़ुदा जिसके लिए चाहे इजाज़त दे दे और पसन्द करे उसके बाद (सिफ़ारिश कर सकते हैं)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (53,27,'An-Najm','إِنَّ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ لَيُسَمُّونَ ٱلۡمَلَٰٓئِكَةَ تَسۡمِيَةَ ٱلۡأُنثَىٰ','جو لوگ آخرت پر ایمان نہیں لاتے وہ فرشتوں کو (خدا کی) لڑکیوں کے نام سے موسوم کرتے ہیں','Indeed, those who do not believe in the Hereafter label angels as female','जो लोग आख़ेरत पर ईमान नहीं रखते वह फ़रिश्तों के नाम रखते हैं औरतों के से नाम हालॉकि उन्हें इसकी कुछ ख़बर नहीं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (53,28,'An-Najm','وَمَا لَهُم بِهِۦ مِنۡ عِلۡمٍۖ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّۖ وَإِنَّ ٱلظَّنَّ لَا يُغۡنِي مِنَ ٱلۡحَقِّ شَيۡـࣰٔ ا','حالانکہ ان کو اس کی کچھ خبر نہیں۔ وہ صرف ظن پر چلتے ہیں۔ اور ظن یقین کے مقابلے میں کچھ کام نہیں آتا','although they have no knowledge ˹in support˺ of this. They follow nothing but ˹inherited˺ assumptions. And surely assumptions can in no way replace the truth','वह लोग तो बस गुमान (ख्याल) के पीछे चल रहे हैं, हालॉकि गुमान यक़ीन के बदले में कुछ भी काम नहीं आया करता');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (53,29,'An-Najm','فَأَعۡرِضۡ عَن مَّن تَوَلَّىٰ عَن ذِكۡرِنَا وَلَمۡ يُرِدۡ إِلَّا ٱلۡحَيَوٰةَ ٱلدُّنۡيَا','تو جو ہماری یاد سے روگردانی اور صرف دنیا ہی کی زندگی کا خواہاں ہو اس سے تم بھی منہ پھیر لو','So turn away ˹O Prophet˺ from whoever has shunned Our Reminder, only seeking the ˹fleeting˺ life of this world','तो जो हमारी याद से रदगिरदानी करे ओर सिर्फ दुनिया की ज़िन्दगी ही का तालिब हो तुम भी उससे मुँह फेर लो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (53,30,'An-Najm','ذَٰلِكَ مَبۡلَغُهُم مِّنَ ٱلۡعِلۡمِۚ إِنَّ رَبَّكَ هُوَ أَعۡلَمُ بِمَن ضَلَّ عَن سَبِيلِهِۦ وَهُوَ أَعۡلَمُ بِمَنِ ٱهۡتَدَىٰ','ان کے علم کی انتہا یہی ہے۔ تمہارا پروردگار اس کو بھی خوب جانتا ہے جو اس کے رستے سے بھٹک گیا اور اس سے بھی خوب واقف ہے جو رستے پر چلا','This is the extent of their knowledge. Surely your Lord knows best who has strayed from His Way and who is ˹rightly˺ guided','उनके इल्म की यही इन्तिहा है तुम्हारा परवरदिगार, जो उसके रास्ते से भटक गया उसको भी ख़ूब जानता है, और जो राहे रास्त पर है उनसे भी ख़ूब वाक़िफ है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (53,31,'An-Najm','وَلِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِ لِيَجۡزِيَ ٱلَّذِينَ أَسَٰٓـُٔواْ بِمَا عَمِلُواْ وَيَجۡزِيَ ٱلَّذِينَ أَحۡسَنُواْ بِٱلۡحُسۡنَى','اور جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں ہے سب خدا ہی کا ہے (اور اس نے خلقت کو) اس لئے (پیدا کیا ہے) کہ جن لوگوں نے برے کام کئے ان کو ان کے اعمال کا (برا) بدلا دے اور جنہوں نے نیکیاں کیں ان کو نیک بدلہ دے','To Allah ˹alone˺ belongs whatever is in the heavens and whatever is on the earth so that He may reward the evildoers according to what they did, and reward the good-doers with the finest reward—','और जो कुछ आसमानों में है और जो कुछ ज़मीन में है (ग़रज़ सब कुछ) ख़ुदा ही का है, ताकि जिन लोगों ने बुराई की हो उनको उनकी कारस्तानियों की सज़ा दे और जिन लोगों ने नेकी की है (उनकी नेकी की जज़ा दे)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (53,32,'An-Najm','ٱلَّذِينَ يَجۡتَنِبُونَ كَبَٰٓئِرَ ٱلۡإِثۡمِ وَٱلۡفَوَٰحِشَ إِلَّا ٱللَّمَمَۚ إِنَّ رَبَّكَ وَٰسِعُ ٱلۡمَغۡفِرَةِۚ هُوَ أَعۡلَمُ بِكُمۡ إِذۡ أَنشَأَكُم مِّنَ ٱلۡأَرۡضِ وَإِذۡ أَنتُمۡ أَجِنَّةࣱ فِي بُطُونِ أُمَّهَٰتِكُمۡۖ فَلَا تُزَكُّوٓاْ أَنفُسَكُمۡۖ هُوَ أَعۡلَمُ بِمَنِ ٱتَّقَىٰٓ','جو صغیرہ گناہوں کے سوا بڑے بڑے گناہوں اور بےحیائی کی باتوں سے اجتناب کرتے ہیں۔ بےشک تمہارا پروردگار بڑی بخشش والا ہے۔ وہ تم کو خوب جانتا ہے۔ جب اس نے تم کو مٹی سے پیدا کیا اور جب تم اپنی ماؤں کے پیٹ میں بچّے تھے۔ تو اپنے آپ کو پاک صاف نہ جتاؤ۔ جو پرہیزگار ہے وہ اس سے خوب واقف ہے','those who avoid major sins and shameful deeds, despite ˹stumbling on˺ minor sins. Surely your Lord is infinite in forgiveness. He knew well what would become of you as He created you from the earth and while you were ˹still˺ fetuses in the wombs of your mothers. So do not ˹falsely˺ elevate yourselves. He knows best who is ˹truly˺ righteous','जो सग़ीरा गुनाहों के सिवा कबीरा गुनाहों से और बेहयाई की बातों से बचे रहते हैं बेशक तुम्हारा परवरदिगार बड़ी बख्यिश वाला है वही तुमको ख़ूब जानता है जब उसने तुमको मिटटी से पैदा किया और जब तुम अपनी माँ के पेट में बच्चे थे तो (तकब्बुर) से अपने नफ्स की पाकीज़गी न जताया करो जो परहेज़गार है उसको वह ख़ूब जानता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (53,33,'An-Najm','أَفَرَءَيۡتَ ٱلَّذِي تَوَلَّىٰ','بھلا تم نے اس شخص کو دیکھا جس نے منہ پھیر لیا','Have you seen the one who turned away ˹from Islam,˺','भला (ऐ रसूल) तुमने उस शख़्श को भी देखा जिसने रदगिरदानी की');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (53,34,'An-Najm','وَأَعۡطَىٰ قَلِيلࣰ ا وَأَكۡدَىٰٓ','اور تھوڑا سا دیا (پھر) ہاتھ روک لیا','and ˹initially˺ paid a little ˹for his salvation˺, and then stopped','और थोड़ा सा (ख़ुदा की राह में) दिया और फिर बन्द कर दिया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (53,35,'An-Najm','أَعِندَهُۥ عِلۡمُ ٱلۡغَيۡبِ فَهُوَ يَرَىٰٓ','کیا اس کے پاس غیب کا علم ہے کہ وہ اس کو دیکھ رہا ہے','Does he have the knowledge of the unseen so that he sees ˹the Hereafter˺','क्या उसके पास इल्मे ग़ैब है कि वह देख रहा है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (53,36,'An-Najm','أَمۡ لَمۡ يُنَبَّأۡ بِمَا فِي صُحُفِ مُوسَىٰ','کیا جو باتیں موسیٰ کے صحیفوں میں ہیں ان کی اس کو خبر نہیں پہنچی','Or has he not been informed of what is in the Scripture of Moses','क्या उसको उन बातों की ख़बर नहीं पहुँची जो मूसा के सहीफ़ों में है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (53,37,'An-Najm','وَإِبۡرَٰهِيمَ ٱلَّذِي وَفَّىٰٓ','اور ابراہیمؑ کی جنہوں نے (حق طاعت ورسالت) پورا کیا','and ˹that of˺ Abraham, who ˹perfectly˺ fulfilled ˹his covenant˺','और इबराहीम के (सहीफ़ों में)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (53,38,'An-Najm','أَلَّا تَزِرُ وَازِرَةࣱ وِزۡرَ أُخۡرَىٰ','یہ کہ کوئی شخص دوسرے (کے گناہ) کا بوجھ نہیں اٹھائے گا','˹They state˺ that no soul burdened with sin will bear the burden of another','जिन्होने (अपना हक़) (पूरा अदा) किया इन सहीफ़ों में ये है, कि कोई शख़्श दूसरे (के गुनाह) का बोझ नहीं उठाएगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (53,39,'An-Najm','وَأَن لَّيۡسَ لِلۡإِنسَٰنِ إِلَّا مَا سَعَىٰ','اور یہ کہ انسان کو وہی ملتا ہے جس کی وہ کوشش کرتا ہے','and that each person will only have what they endeavoured towards','और ये कि इन्सान को वही मिलता है जिसकी वह कोशिश करता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (53,40,'An-Najm','وَأَنَّ سَعۡيَهُۥ سَوۡفَ يُرَىٰ','اور یہ کہ اس کی کوشش دیکھی جائے گی','and that ˹the outcome of˺ their endeavours will be seen ˹in their record˺','और ये कि उनकी कोशिश अनक़रीेब ही (क़यामत में) देखी जाएगी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (53,41,'An-Najm','ثُمَّ يُجۡزَىٰهُ ٱلۡجَزَآءَ ٱلۡأَوۡفَىٰ','پھر اس کو اس کا پورا پورا بدلا دیا جائے گا','then they will be fully rewarded','फिर उसका पूरा पूरा बदला दिया जाएगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (53,42,'An-Najm','وَأَنَّ إِلَىٰ رَبِّكَ ٱلۡمُنتَهَىٰ','اور یہ کہ تمہارے پروردگار ہی کے پاس پہنچنا ہے','and that to your Lord ˹alone˺ is the ultimate return ˹of all things˺','और ये कि (सबको आख़िर) तुम्हारे परवरदिगार ही के पास पहुँचना है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (53,43,'An-Najm','وَأَنَّهُۥ هُوَ أَضۡحَكَ وَأَبۡكَىٰ','اور یہ کہ وہ ہنساتا اور رلاتا ہے','Moreover, He is the One Who brings about joy and sadness','और ये कि वही हँसाता और रूलाता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (53,44,'An-Najm','وَأَنَّهُۥ هُوَ أَمَاتَ وَأَحۡيَا','اور یہ کہ وہی مارتا اور جلاتا ہے','And He is the One Who gives life and causes death','और ये कि वही मारता और जिलाता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (53,45,'An-Najm','وَأَنَّهُۥ خَلَقَ ٱلزَّوۡجَيۡنِ ٱلذَّكَرَ وَٱلۡأُنثَىٰ','اور یہ کہ وہی نر اور مادہ دو قسم (کے حیوان) پیدا کرتا ہے','And He created the pairs—males and females—','और ये कि वही नर और मादा दो किस्म (के हैवान) नुत्फे से जब (रहम में) डाला जाता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (53,46,'An-Najm','مِن نُّطۡفَةٍ إِذَا تُمۡنَىٰ','(یعنی) نطفے سے جو (رحم میں) ڈالا جاتا ہے','from a sperm-drop when it is emitted','पैदा करता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (53,47,'An-Najm','وَأَنَّ عَلَيۡهِ ٱلنَّشۡأَةَ ٱلۡأُخۡرَىٰ','اور یہ کہ (قیامت کو) اسی پر دوبارہ اٹھانا لازم ہے','And it is upon Him to bring about re-creation','और ये कि उसी पर (कयामत में) दोबारा उठाना लाज़िम है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (53,48,'An-Najm','وَأَنَّهُۥ هُوَ أَغۡنَىٰ وَأَقۡنَىٰ','اور یہ کہ وہی دولت مند بناتا اور مفلس کرتا ہے','And He is the One Who enriches and impoverishes','और ये कि वही मालदार बनाता है और सरमाया अता करता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (53,49,'An-Najm','وَأَنَّهُۥ هُوَ رَبُّ ٱلشِّعۡرَىٰ','اور یہ کہ وہی شعریٰ کا مالک ہے','And He alone is the Lord of Sirius','और ये कि वही योअराए का मालिक है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (53,50,'An-Najm','وَأَنَّهُۥٓ أَهۡلَكَ عَادًا ٱلۡأُولَىٰ','اور یہ کہ اسی نے عاد اول کو ہلاک کر ڈالا','And He destroyed the first ˹people of˺ ’Ȃd','और ये कि उसी ने पहले (क़ौमे) आद को हलाक किया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (53,51,'An-Najm','وَثَمُودَاْ فَمَآ أَبۡقَىٰ','اور ثمود کو بھی۔ غرض کسی کو باقی نہ چھوڑا','and ˹then˺ Thamûd, sparing no one','और समूद को भी ग़रज़ किसी को बाक़ी न छोड़ा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (53,52,'An-Najm','وَقَوۡمَ نُوحࣲ مِّن قَبۡلُۖ إِنَّهُمۡ كَانُواْ هُمۡ أَظۡلَمَ وَأَطۡغَىٰ','اور ان سے پہلے قوم نوحؑ کو بھی۔ کچھ شک نہیں کہ وہ لوگ بڑے ہی ظالم اور بڑے ہی سرکش تھے','And before ˹that He destroyed˺ the people of Noah, who were truly far worse in wrongdoing and transgression','और (उसके) पहले नूह की क़ौम को बेशक ये लोग बड़े ही ज़ालिम और बड़े ही सरकश थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (53,53,'An-Najm','وَٱلۡمُؤۡتَفِكَةَ أَهۡوَىٰ','اور اسی نے الٹی ہوئی بستیوں کو دے پٹکا','And ˹it was˺ He ˹Who˺ turned the cities ˹of Sodom and Gomorrah˺ upside down','और उसी ने (क़ौमे लूत की) उलटी हुई बस्तियों को दे पटका');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (53,54,'An-Najm','فَغَشَّىٰهَا مَا غَشَّىٰ','پھر ان پر چھایا جو چھایا','How overwhelming was what covered ˹them˺','(फिर उन पर) जो छाया सो छाया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (53,55,'An-Najm','فَبِأَيِّ ءَالَآءِ رَبِّكَ تَتَمَارَىٰ','تو (اے انسان) تو اپنے پروردگار کی کون سی نعمت پر جھگڑے گا','Now, which of your Lord’s favours will you dispute','तो तू (ऐ इन्सान आख़िर) अपने परवरदिगार की कौन सी नेअमत पर शक़ किया करेगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (53,56,'An-Najm','هَٰذَا نَذِيرࣱ مِّنَ ٱلنُّذُرِ ٱلۡأُولَىٰٓ','یہ (محمدﷺ) بھی اگلے ڈر سنانے والوں میں سے ایک ڈر سنانے والے ہیں','This ˹Prophet˺ is a warner like earlier ones','ये (मोहम्मद भी अगले डराने वाले पैग़म्बरों में से एक डरने वाला) पैग़म्बर है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (53,57,'An-Najm','أَزِفَتِ ٱلۡأٓزِفَةُ','آنے والی (یعنی قیامت) قریب آ پہنچی','The approaching ˹Hour˺ has drawn near','कयामत क़रीब आ गयी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (53,58,'An-Najm','لَيۡسَ لَهَا مِن دُونِ ٱللَّهِ كَاشِفَةٌ','اس (دن کی تکلیفوں) کو خدا کے سوا کوئی دور نہیں کرسکے گا','None but Allah can disclose it','ख़ुदा के सिवा उसे कोई टाल नहीं सकता');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (53,59,'An-Najm','أَفَمِنۡ هَٰذَا ٱلۡحَدِيثِ تَعۡجَبُونَ','(اے منکرین خدا) کیا تم اس کلام سے تعجب کرتے ہو؟','Do you find this revelation astonishing','तो क्या तुम लोग इस बात से ताज्जुब करते हो और हँसते हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (53,60,'An-Najm','وَتَضۡحَكُونَ وَلَا تَبۡكُونَ','اور ہنستے ہو اور روتے نہیں؟','laughing ˹at it˺ and not weeping ˹in awe˺','और रोते नहीं हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (53,61,'An-Najm','وَأَنتُمۡ سَٰمِدُونَ','اور تم غفلت میں پڑ رہے ہو','while persisting in heedlessness','और तुम इस क़दर ग़ाफ़िल हो तो ख़ुदा के आगे सजदे किया करो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (53,62,'An-Najm','فَٱسۡجُدُواْۤ لِلَّهِۤ وَٱعۡبُدُواْ۩','تو خدا کے آگے سجدہ کرو اور (اسی کی) عبادت کرو','Instead, prostrate to Allah and worship ˹Him alone˺','और (उसी की) इबादत किया करो (62) सजदा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (54,1,'Al-Qamar','ٱقۡتَرَبَتِ ٱلسَّاعَةُ وَٱنشَقَّ ٱلۡقَمَرُ','قیامت قریب آ پہنچی اور چاند شق ہوگیا','The Hour has drawn near and the moon was split ˹in two˺','क़यामत क़रीब आ गयी और चाँद दो टुकड़े हो गया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (54,2,'Al-Qamar','وَإِن يَرَوۡاْ ءَايَةࣰ يُعۡرِضُواْ وَيَقُولُواْ سِحۡرࣱ مُّسۡتَمِرࣱّ‏','اور اگر (کافر) کوئی نشانی دیکھتے ہیں تو منہ پھیر لیتے ہیں اور کہتے ہیں کہ یہ ایک ہمیشہ کا جادو ہے','Yet, whenever they see a sign, they turn away, saying, “Same old magic!”','और अगर ये कुफ्फ़ार कोई मौजिज़ा देखते हैं, तो मुँह फेर लेते हैं, और कहते हैं कि ये तो बड़ा ज़बरदस्त जादू है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (54,3,'Al-Qamar','وَكَذَّبُواْ وَٱتَّبَعُوٓاْ أَهۡوَآءَهُمۡۚ وَكُلُّ أَمۡرࣲ مُّسۡتَقِرࣱّ‏','اور انہوں نے جھٹلایا اور اپنی خواہشوں کی پیروی کی اور ہر کام کا وقت مقرر ہے','They rejected ˹the truth˺ and followed their own desires—and every matter will be settled—','और उन लोगों ने झुठलाया और अपनी नफ़सियानी ख्वाहिशों की पैरवी की, और हर काम का वक्त मुक़र्रर है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (54,4,'Al-Qamar','وَلَقَدۡ جَآءَهُم مِّنَ ٱلۡأَنۢبَآءِ مَا فِيهِ مُزۡدَجَرٌ','اور ان کو ایسے حالات (سابقین) پہنچ چکے ہیں جن میں عبرت ہے','even though the stories ˹of destroyed nations˺ that have already come to them are a sufficient deterrent','और उनके पास तो वह हालात पहुँच चुके हैं जिनमें काफी तम्बीह थीं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (54,5,'Al-Qamar','حِكۡمَةُۢ بَٰلِغَةࣱۖ فَمَا تُغۡنِ ٱلنُّذُرُ','اور کامل دانائی (کی کتاب بھی) لیکن ڈرانا ان کو کچھ فائدہ نہیں دیتا','˹This Quran is˺ profound ˹in˺ wisdom, but warnings are of no benefit ˹to them˺','और इन्तेहा दर्जे की दानाई मगर (उनको तो) डराना कुछ फ़ायदा नहीं देता');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (54,6,'Al-Qamar','فَتَوَلَّ عَنۡهُمۡۘ يَوۡمَ يَدۡعُ ٱلدَّاعِ إِلَىٰ شَيۡءࣲ نُّكُرٍ','تو تم بھی ان کی کچھ پروا نہ کرو۔ جس دن بلانے والا ان کو ایک ناخوش چیز کی طرف بلائے گا','So turn away from them ˹O Prophet˺. ˹And wait for˺ the Day ˹when˺ the caller will summon ˹them˺ for something horrifying','तो (ऐ रसूल) तुम भी उनसे किनाराकश रहो, जिस दिन एक बुलाने वाला (इसराफ़ील) एक अजनबी और नागवार चीज़ की तरफ़ बुलाएगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (54,7,'Al-Qamar','خُشَّعًا أَبۡصَٰرُهُمۡ يَخۡرُجُونَ مِنَ ٱلۡأَجۡدَاثِ كَأَنَّهُمۡ جَرَادࣱ مُّنتَشِرࣱ‏','تو آنکھیں نیچی کئے ہوئے قبروں سے نکل پڑیں گے گویا بکھری ہوئی ٹڈیاں','With eyes downcast, they will come forth from the graves as if they were swarming locusts','तो (निदामत से) ऑंखें नीचे किए हुए कब्रों से निकल पड़ेंगे गोया वह फैली हुई टिड्डियाँ हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (54,8,'Al-Qamar','مُّهۡطِعِينَ إِلَى ٱلدَّاعِۖ يَقُولُ ٱلۡكَٰفِرُونَ هَٰذَا يَوۡمٌ عَسِرࣱ‏','اس بلانے والے کی طرف دوڑتے جاتے ہوں گے۔ کافر کہیں گے یہ دن بڑا سخت ہے','rushing towards the caller. The disbelievers will cry, “This is a difficult Day!”','(और) बुलाने वाले की तरफ गर्दनें बढ़ाए दौड़ते जाते होंगे, कुफ्फ़ार कहेंगे ये तो बड़ा सख्त दिन है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (54,9,'Al-Qamar','۞كَذَّبَتۡ قَبۡلَهُمۡ قَوۡمُ نُوحࣲ فَكَذَّبُواْ عَبۡدَنَا وَقَالُواْ مَجۡنُونࣱ وَٱزۡدُجِرَ','ان سے پہلے نوحؑ کی قوم نے بھی تکذیب کی تھی تو انہوں نے ہمارے بندے کو جھٹلایا اور کہا کہ دیوانہ ہے اور انہیں ڈانٹا بھی','Before them, the people of Noah denied ˹the truth˺ and rejected Our servant, calling ˹him˺ insane. And he was intimidated','इनसे पहले नूह की क़ौम ने भी झुठलाया था, तो उन्होने हमारे (ख़ास) बन्दे (नूह) को झुठलाया, और कहने लगे ये तो दीवाना है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (54,10,'Al-Qamar','فَدَعَا رَبَّهُۥٓ أَنِّي مَغۡلُوبࣱ فَٱنتَصِرۡ','تو انہوں نے اپنے پروردگار سے دعا کی کہ (بار الٓہا) میں (ان کے مقابلے میں) کمزور ہوں تو (ان سے) بدلہ لے','So he cried out to his Lord, “I am helpless, so help ˹me˺!”','और उनको झिड़कियाँ भी दी गयीं, तो उन्होंने अपने परवरदिगार से दुआ की कि (बारे इलाहा मैं) इनके मुक़ाबले में कमज़ोर हूँ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (54,11,'Al-Qamar','فَفَتَحۡنَآ أَبۡوَٰبَ ٱلسَّمَآءِ بِمَآءࣲ مُّنۡهَمِرࣲ‏','پس ہم نے زور کے مینہ سے آسمان کے دہانے کھول دیئے','So We opened the gates of the sky with pouring rain','तो अब तू ही (इनसे) बदला ले तो हमने मूसलाधार पानी से आसमान के दरवाज़े खोल दिए');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (54,12,'Al-Qamar','وَفَجَّرۡنَا ٱلۡأَرۡضَ عُيُونࣰ ا فَٱلۡتَقَى ٱلۡمَآءُ عَلَىٰٓ أَمۡرࣲ قَدۡ قُدِرَ','اور زمین میں چشمے جاری کردیئے تو پانی ایک کام کے لئے جو مقدر ہوچکا تھا جمع ہوگیا','and caused the earth to burst with springs, so the waters met for a fate already set','और ज़मीन से चश्में जारी कर दिए, तो एक काम के लिए जो मुक़र्रर हो चुका था (दोनों) पानी मिलकर एक हो गया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (54,13,'Al-Qamar','وَحَمَلۡنَٰهُ عَلَىٰ ذَاتِ أَلۡوَٰحࣲ وَدُسُرࣲ‏','اور ہم نے نوحؑ کو ایک کشتی پر جو تختوں اور میخوں سے تیار کی گئی تھی سوار کرلیا','We carried him on that ˹Ark made˺ of planks and nails','और हमने एक कश्ती पर जो तख्तों और कीलों से तैयार की गयी थी सवार किया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (54,14,'Al-Qamar','تَجۡرِي بِأَعۡيُنِنَا جَزَآءࣰ لِّمَن كَانَ كُفِرَ','وہ ہماری آنکھوں کے سامنے چلتی تھی۔ (یہ سب کچھ) اس شخص کے انتقام کے لئے (کیا گیا) جس کو کافر مانتے نہ تھے','sailing under Our ˹watchful˺ Eyes—a ˹fair˺ punishment on behalf of the one ˹they˺ denied','और वह हमारी निगरानी में चल रही थी (ये) उस शख़्श (नूह) का बदला लेने के लिए जिसको लोग न मानते थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (54,15,'Al-Qamar','وَلَقَد تَّرَكۡنَٰهَآ ءَايَةࣰ فَهَلۡ مِن مُّدَّكِرࣲ‏','اور ہم نے اس کو ایک عبرت بنا چھوڑا تو کوئی ہے کہ سوچے سمجھے؟','We certainly left this as a sign. So is there anyone who will be mindful','और हमने उसको एक इबरत बना कर छोड़ा तो कोई है जो इबरत हासिल करे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (54,16,'Al-Qamar','فَكَيۡفَ كَانَ عَذَابِي وَنُذُرِ','سو (دیکھ لو کہ) میرا عذاب اور ڈرانا کیسا ہوا؟','Then how ˹dreadful˺ were My punishment and warnings','तो (उनको) मेरा अज़ाब और डराना कैसा था');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (54,17,'Al-Qamar','وَلَقَدۡ يَسَّرۡنَا ٱلۡقُرۡءَانَ لِلذِّكۡرِ فَهَلۡ مِن مُّدَّكِرࣲ‏','اور ہم نے قرآن کو سمجھنے کے لئے آسان کردیا ہے تو کوئی ہے کہ سوچے سمجھے؟','And We have certainly made the Quran easy to remember. So is there anyone who will be mindful','और हमने तो क़ुरान को नसीहत हासिल करने के वास्ते आसान कर दिया है तो कोई है जो नसीहत हासिल करे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (54,18,'Al-Qamar','كَذَّبَتۡ عَادࣱ فَكَيۡفَ كَانَ عَذَابِي وَنُذُرِ','عاد نے بھی تکذیب کی تھی سو (دیکھ لو کہ) میرا عذاب اور ڈرانا کیسا ہوا','’Ȃd ˹also˺ rejected ˹the truth˺. Then how ˹dreadful˺ were My punishment and warnings','आद (की क़ौम ने) (अपने पैग़म्बर) को झुठलाया तो (उनका) मेरा अज़ाब और डराना कैसा था');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (54,19,'Al-Qamar','إِنَّآ أَرۡسَلۡنَا عَلَيۡهِمۡ رِيحࣰ ا صَرۡصَرࣰ ا فِي يَوۡمِ نَحۡسࣲ مُّسۡتَمِرࣲّ‏','ہم نے ان پر سخت منحوس دن میں آندھی چلائی','Indeed, We sent against them a furious wind, on a day of unrelenting misery','हमने उन पर बहुत सख्त मनहूस दिन में बड़े ज़न्नाटे की ऑंधी चलायी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (54,20,'Al-Qamar','تَنزِعُ ٱلنَّاسَ كَأَنَّهُمۡ أَعۡجَازُ نَخۡلࣲ مُّنقَعِرࣲ‏','وہ لوگوں کو (اس طرح) اکھیڑے ڈالتی تھی گویا اکھڑی ہوئی کھجوروں کے تنے ہیں','that snatched people up, leaving them like trunks of uprooted palm trees','जो लोगों को (अपनी जगह से) इस तरह उखाड़ फेकती थी गोया वह उखड़े हुए खजूर के तने हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (54,21,'Al-Qamar','فَكَيۡفَ كَانَ عَذَابِي وَنُذُرِ','سو (دیکھ لو کہ) میرا عذاب اور ڈرانا کیسا ہوا','Then how ˹dreadful˺ were My punishment and warnings','तो (उनको) मेरा अज़ाब और डराना कैसा था');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (54,22,'Al-Qamar','وَلَقَدۡ يَسَّرۡنَا ٱلۡقُرۡءَانَ لِلذِّكۡرِ فَهَلۡ مِن مُّدَّكِرࣲ‏','اور ہم نے قرآن کو سمجھنے کے لئے آسان کردیا ہے تو کوئی ہے کہ سوچے سمجھے؟','And We have certainly made the Quran easy to remember. So is there anyone who will be mindful','और हमने तो क़ुरान को नसीहत हासिल करने के वास्ते आसान कर दिया, तो कोई है जो नसीहत हासिल करे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (54,23,'Al-Qamar','كَذَّبَتۡ ثَمُودُ بِٱلنُّذُرِ','ثمود نے بھی ہدایت کرنے والوں کو جھٹلایا','Thamûd rejected the warnings ˹as well˺','(क़ौम) समूद ने डराने वाले (पैग़म्बरों) को झुठलाया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (54,24,'Al-Qamar','فَقَالُوٓاْ أَبَشَرࣰ ا مِّنَّا وَٰحِدࣰ ا نَّتَّبِعُهُۥٓ إِنَّآ إِذࣰ ا لَّفِي ضَلَٰلࣲ وَسُعُرٍ','اور کہا کہ بھلا ایک آدمی جو ہم ہی میں سے ہے ہم اس کی پیروی کریں؟ یوں ہو تو ہم گمراہی اور دیوانگی میں پڑ گئے','arguing, “How can we follow one ˹average˺ human being from among us? We would then truly be misguided and insane','तो कहने लगे कि भला एक आदमी की जो हम ही में से हो उसकी पैरवीं करें ऐसा करें तो गुमराही और दीवानगी में पड़ गए');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (54,25,'Al-Qamar','أَءُلۡقِيَ ٱلذِّكۡرُ عَلَيۡهِ مِنۢ بَيۡنِنَا بَلۡ هُوَ كَذَّابٌ أَشِرࣱ‏','کیا ہم سب میں سے اسی پر وحی نازل ہوئی ہے؟ (نہیں) بلکہ یہ جھوٹا خود پسند ہے','Has the revelation been sent down ˹only˺ to him out of ˹all of˺ us? In fact, he is a boastful liar.”','क्या हम सबमें बस उसी पर वही नाज़िल हुई है (नहीं) बल्कि ये तो बड़ा झूठा तअल्ली करने वाला है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (54,26,'Al-Qamar','سَيَعۡلَمُونَ غَدࣰ ا مَّنِ ٱلۡكَذَّابُ ٱلۡأَشِرُ','ان کو کل ہی معلوم ہوجائے گا کہ کون جھوٹا خود پسند ہے','˹It was revealed to Ṣâliḥ,˺ “They will soon know who the boastful liar is','उनको अनक़रीब कल ही मालूम हो जाएगा कि कौन बड़ा झूठा तकब्बुर करने वाला है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (54,27,'Al-Qamar','إِنَّا مُرۡسِلُواْ ٱلنَّاقَةِ فِتۡنَةࣰ لَّهُمۡ فَٱرۡتَقِبۡهُمۡ وَٱصۡطَبِرۡ','(اے صالح) ہم ان کی آزمائش کے لئے اونٹنی بھیجنے والے ہیں تو تم ان کو دیکھتے رہو اور صبر کرو','We are sending the she-camel as a test for them. So watch them ˹closely˺, and have patience','(ऐ सालेह) हम उनकी आज़माइश के लिए ऊँटनी भेजने वाले हैं तो तुम उनको देखते रहो और (थोड़ा) सब्र करो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (54,28,'Al-Qamar','وَنَبِّئۡهُمۡ أَنَّ ٱلۡمَآءَ قِسۡمَةُۢ بَيۡنَهُمۡۖ كُلُّ شِرۡبࣲ مُّحۡتَضَرࣱ‏','اور ان کو آگاہ کردو کہ ان میں پانی کی باری مقرر کر دی گئی ہے۔ ہر (باری والے کو اپنی) باری پر آنا چاہیئے','And tell them that the ˹drinking˺ water must be divided between them ˹and her˺, each taking a turn to drink ˹every other day˺.”','और उनको ख़बर कर दो कि उनमें पानी की बारी मुक़र्रर कर दी गयी है हर (बारी वाले को अपनी) बारी पर हाज़िर होना चाहिए');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (54,29,'Al-Qamar','فَنَادَوۡاْ صَاحِبَهُمۡ فَتَعَاطَىٰ فَعَقَرَ','تو ان لوگوں نے اپنے رفیق کو بلایا اور اس نے (اونٹنی کو پکڑ کر اس کی) کونچیں کاٹ ڈالیں','But they roused a companion of theirs, so he dared to kill ˹her˺','तो उन लोगों ने अपने रफीक़ (क़ेदार) को बुलाया तो उसने पकड़ कर (ऊँटनी की) कूंचे काट डालीं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (54,30,'Al-Qamar','فَكَيۡفَ كَانَ عَذَابِي وَنُذُرِ','سو (دیکھ لو کہ) میرا عذاب اور ڈرانا کیسا ہوا','Then how ˹dreadful˺ were My punishment and warnings','तो (देखो) मेरा अज़ाब और डराना कैसा था');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (54,31,'Al-Qamar','إِنَّآ أَرۡسَلۡنَا عَلَيۡهِمۡ صَيۡحَةࣰ وَٰحِدَةࣰ فَكَانُواْ كَهَشِيمِ ٱلۡمُحۡتَظِرِ','ہم نے ان پر (عذاب کے لئے) ایک چیخ بھیجی تو وہ ایسے ہوگئے جیسے باڑ والے کی سوکھی اور ٹوٹی ہوئی باڑ','Indeed, We sent against them ˹only˺ one ˹mighty˺ blast, leaving them like the twigs of fence-builders','हमने उन पर एक सख्त चिंघाड़ (का अज़ाब) भेज दिया तो वह बाड़े वालो के सूखे हुए चूर चूर भूसे की तरह हो गए');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (54,32,'Al-Qamar','وَلَقَدۡ يَسَّرۡنَا ٱلۡقُرۡءَانَ لِلذِّكۡرِ فَهَلۡ مِن مُّدَّكِرࣲ‏','اور ہم نے قرآن کو سمجھنے کے لئے آسان کردیا ہے تو کوئی ہے کہ سوچے سمجھے؟','And We have certainly made the Quran easy to remember. So is there anyone who will be mindful','और हमने क़ुरान को नसीहत हासिल करने के वास्ते आसान कर दिया है तो कोई है जो नसीहत हासिल करे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (54,33,'Al-Qamar','كَذَّبَتۡ قَوۡمُ لُوطِۭ بِٱلنُّذُرِ','لوط کی قوم نے بھی ڈر سنانے والوں کو جھٹلایا تھا','The people of Lot ˹also˺ rejected the warnings','लूत की क़ौम ने भी डराने वाले (पैग़म्बरों) को झुठलाया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (54,34,'Al-Qamar','إِنَّآ أَرۡسَلۡنَا عَلَيۡهِمۡ حَاصِبًا إِلَّآ ءَالَ لُوطࣲۖ نَّجَّيۡنَٰهُم بِسَحَرࣲ‏','تو ہم نے ان پر کنکر بھری ہوا چلائی مگر لوط کے گھر والے کہ ہم نے ان کو پچھلی رات ہی سے بچا لیا','We unleashed upon them a storm of stones. As for ˹the believers of˺ Lot’s family, We delivered them before dawn','तो हमने उन पर कंकर भरी हवा चलाई मगर लूत के लड़के बाले को हमने उनको अपने फज़ल व करम से पिछले ही को बचा लिया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (54,35,'Al-Qamar','نِّعۡمَةࣰ مِّنۡ عِندِنَاۚ كَذَٰلِكَ نَجۡزِي مَن شَكَرَ','اپنے فضل سے۔ شکر کرنے والوں کو ہم ایسا ہی بدلہ دیا کرتے ہیں','as a blessing from Us. This is how We reward whoever gives thanks','हम शुक्र करने वालों को ऐसा ही बदला दिया करते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (54,36,'Al-Qamar','وَلَقَدۡ أَنذَرَهُم بَطۡشَتَنَا فَتَمَارَوۡاْ بِٱلنُّذُرِ','اور لوطؑ نے ان کو ہماری پکڑ سے ڈرایا بھی تھا مگر انہوں نے ڈرانے میں شک کیا','He had already warned them of Our ˹crushing˺ blow but they disputed the warnings','और लूत ने उनको हमारी पकड़ से भी डराया था मगर उन लोगों ने डराते ही में शक़ किया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (54,37,'Al-Qamar','وَلَقَدۡ رَٰوَدُوهُ عَن ضَيۡفِهِۦ فَطَمَسۡنَآ أَعۡيُنَهُمۡ فَذُوقُواْ عَذَابِي وَنُذُرِ','اور ان سے ان کے مہمانوں کو لے لینا چاہا تو ہم نے ان کی آنکھیں مٹا دیں سو (اب) میرے عذاب اور ڈرانے کے مزے چکھو','And they even demanded his angel-guests from him, so We blinded their eyes. ˹And they were told,˺ “Taste then My punishment and warnings!”','और उनसे उनके मेहमान (फ़रिश्ते) के बारे में नाजायज़ मतलब की ख्वाहिश की तो हमने उनकी ऑंखें अन्धी कर दीं तो मेरे अज़ाब और डराने का मज़ा चखो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (54,38,'Al-Qamar','وَلَقَدۡ صَبَّحَهُم بُكۡرَةً عَذَابࣱ مُّسۡتَقِرࣱّ‏','اور ان پر صبح سویرے ہی اٹل عذاب آ نازل ہوا','And indeed, by the early morning they were overwhelmed by an unrelenting torment','और सुबह सवेरे ही उन पर अज़ाब आ गया जो किसी तरह टल ही नहीं सकता था');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (54,39,'Al-Qamar','فَذُوقُواْ عَذَابِي وَنُذُرِ','تو اب میرے عذاب اور ڈرانے کے مزے چکھو','˹Again they were told,˺ “Taste now My punishment and warnings!”','तो मेरे अज़ाब और डराने के (पड़े) मज़े चखो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (54,40,'Al-Qamar','وَلَقَدۡ يَسَّرۡنَا ٱلۡقُرۡءَانَ لِلذِّكۡرِ فَهَلۡ مِن مُّدَّكِرࣲ‏','اور ہم نے قرآن کو سمجھنے کے لئے آسان کردیا ہے تو کوئی ہے کہ سوچے سمجھے؟','And We have certainly made the Quran easy to remember. So is there anyone who will be mindful','और हमने तो क़ुरान को नसीहत हासिल करने के वास्ते आसान कर दिया तो कोई है जो नसीहत हासिल करे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (54,41,'Al-Qamar','وَلَقَدۡ جَآءَ ءَالَ فِرۡعَوۡنَ ٱلنُّذُرُ','اور قوم فرعون کے پاس بھی ڈر سنانے والے آئے','And indeed, the warnings ˹also˺ came to the people of Pharaoh','और फिरऔन के पास भी डराने वाले (पैग़म्बर) आए');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (54,42,'Al-Qamar','كَذَّبُواْ بِـَٔايَٰتِنَا كُلِّهَا فَأَخَذۡنَٰهُمۡ أَخۡذَ عَزِيزࣲ مُّقۡتَدِرٍ','انہوں نے ہماری تمام نشانیوں کو جھٹلایا تو ہم نے ان کو اس طرح پکڑ لیا جس طرح ایک قوی اور غالب شخص پکڑ لیتا ہے','˹But˺ they rejected all of Our signs, so We seized them with the ˹crushing˺ grip of the Almighty, Most Powerful','तो उन लोगों ने हमारी कुल निशानियों को झुठलाया तो हमने उनको इस तरह सख्त पकड़ा जिस तरह एक ज़बरदस्त साहिबे क़ुदरत पकड़ा करता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (54,43,'Al-Qamar','أَكُفَّارُكُمۡ خَيۡرࣱ مِّنۡ أُوْلَٰٓئِكُمۡ أَمۡ لَكُم بَرَآءَةࣱ فِي ٱلزُّبُرِ','(اے اہل عرب) کیا تمہارے کافر ان لوگوں سے بہتر ہیں یا تمہارے لئے (پہلی) کتابوں میں کوئی فارغ خطی لکھ دی گئی ہے','Now, are you ˹Meccan˺ disbelievers superior to those ˹destroyed peoples˺? Or have you ˹been granted˺ immunity ˹from punishment˺ in divine Books','(ऐ अहले मक्का) क्या उन लोगों से भी तुम्हारे कुफ्फार बढ़ कर हैं या तुम्हारे वास्ते (पहली) किताबों में माफी (लिखी हुई) है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (54,44,'Al-Qamar','أَمۡ يَقُولُونَ نَحۡنُ جَمِيعࣱ مُّنتَصِرࣱ‏','کیا یہ لوگ کہتے ہیں کہ ہماری جماعت بڑی مضبوط ہے','Or do they say, “We are all ˹a˺ united ˹front˺, bound to prevail.”','क्या ये लोग कहते हैं कि हम बहुत क़वी जमाअत हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (54,45,'Al-Qamar','سَيُهۡزَمُ ٱلۡجَمۡعُ وَيُوَلُّونَ ٱلدُّبُرَ','عنقریب یہ جماعت شکست کھائے گی اور یہ لوگ پیٹھ پھیر کر بھاگ جائیں گے','˹Soon˺ their united front will be defeated and ˹forced to˺ flee','अनक़रीब ही ये जमाअत शिकस्त खाएगी और ये लोग पीठ फेर कर भाग जाएँगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (54,46,'Al-Qamar','بَلِ ٱلسَّاعَةُ مَوۡعِدُهُمۡ وَٱلسَّاعَةُ أَدۡهَىٰ وَأَمَرُّ','ان کے وعدے کا وقت تو قیامت ہے اور قیامت بڑی سخت اور بہت تلخ ہے','Better yet, the Hour is their appointed time—and the Hour will be most catastrophic and most bitter','बात ये है कि इनके वायदे का वक्त क़यामत है और क़यामत बड़ी सख्त और बड़ी तल्ख़ (चीज़) है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (54,47,'Al-Qamar','إِنَّ ٱلۡمُجۡرِمِينَ فِي ضَلَٰلࣲ وَسُعُرࣲ‏','بےشک گنہگار لوگ گمراہی اور دیوانگی میں (مبتلا) ہیں','Indeed, the wicked are ˹entrenched˺ in misguidance, and ˹are bound for˺ blazes','बेशक गुनाहगार लोग गुमराही और दीवानगी में (मुब्तिला) हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (54,48,'Al-Qamar','يَوۡمَ يُسۡحَبُونَ فِي ٱلنَّارِ عَلَىٰ وُجُوهِهِمۡ ذُوقُواْ مَسَّ سَقَرَ','اس روز منہ کے بل دوزخ میں گھسیٹے جائیں گے اب آگ کا مزہ چکھو','On the Day they will be dragged into the Fire on their faces, ˹they will be told,˺ “Taste the touch of Hell!”','उस रोज़ ये लोग अपने अपने मुँह के बल (जहन्नुम की) आग में घसीटे जाएँगे (और उनसे कहा जाएगा) अब जहन्नुम की आग का मज़ा चखो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (54,49,'Al-Qamar','إِنَّا كُلَّ شَيۡءٍ خَلَقۡنَٰهُ بِقَدَرࣲ‏','ہم نے ہر چیز اندازہٴ مقرر کے ساتھ پیدا کی ہے','Indeed, We have created everything, perfectly preordained','बेशक हमने हर चीज़ एक मुक़र्रर अन्दाज़ से पैदा की है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (54,50,'Al-Qamar','وَمَآ أَمۡرُنَآ إِلَّا وَٰحِدَةࣱ كَلَمۡحِۭ بِٱلۡبَصَرِ','اور ہمارا حکم تو آنکھ کے جھپکنے کی طرح ایک بات ہوتی ہے','Our command is but a single word, done in the blink of an eye','और हमारा हुक्म तो बस ऑंख के झपकने की तरह एक बात होती है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (54,51,'Al-Qamar','وَلَقَدۡ أَهۡلَكۡنَآ أَشۡيَاعَكُمۡ فَهَلۡ مِن مُّدَّكِرࣲ‏','اور ہم تمہارے ہم مذہبوں کو ہلاک کرچکے ہیں تو کوئی ہے کہ سوچے سمجھے؟','We have already destroyed the likes of you. So will any ˹of you˺ be mindful','और हम तुम्हारे हम मशरबो को हलाक कर चुके हैं तो कोई है जो नसीहत हासिल करे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (54,52,'Al-Qamar','وَكُلُّ شَيۡءࣲ فَعَلُوهُ فِي ٱلزُّبُرِ','اور جو کچھ انہوں نے کیا، (ان کے) اعمال ناموں میں (مندرج) ہے','Everything they have done is ˹listed˺ in ˹their˺ records','और अगर चे ये लोग जो कुछ कर चुके हैं (इनके) आमाल नामों में (दर्ज) है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (54,53,'Al-Qamar','وَكُلُّ صَغِيرࣲ وَكَبِيرࣲ مُّسۡتَطَرٌ','(یعنی) ہر چھوٹا اور بڑا کام لکھ دیا گیا ہے','Every matter, small and large, is written ˹precisely˺','(यानि) हर छोटा और बड़ा काम लिख दिया गया है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (54,54,'Al-Qamar','إِنَّ ٱلۡمُتَّقِينَ فِي جَنَّٰتࣲ وَنَهَرࣲ‏','جو پرہیزگار ہیں وہ باغوں اور نہروں میں ہوں گے','Indeed, the righteous will be amid Gardens and rivers','बेशक परहेज़गार लोग (बेहिश्त के) बाग़ों और नहरों में');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (54,55,'Al-Qamar','فِي مَقۡعَدِ صِدۡقٍ عِندَ مَلِيكࣲ مُّقۡتَدِرِۭ','(یعنی) پاک مقام میں ہر طرح کی قدرت رکھنے والے بادشاہ کی بارگاہ میں','at the Seat of Honour in the presence of the Most Powerful Sovereign','(यानि) पसन्दीदा मक़ाम में हर तरह की कुदरत रखने वाले बादशाह की बारगाह में (मुक़र्रिब) होंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,1,'Ar-Rahmaan','ٱلرَّحۡمَٰنُ','(خدا جو) نہایت مہربان','The Most Compassionate','बड़ा मेहरबान (ख़ुदा)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,2,'Ar-Rahmaan','عَلَّمَ ٱلۡقُرۡءَانَ','اسی نے قرآن کی تعلیم فرمائی','taught the Quran','उसी ने क़ुरान की तालीम फरमाई');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,3,'Ar-Rahmaan','خَلَقَ ٱلۡإِنسَٰنَ','اسی نے انسان کو پیدا کیا','created humanity','उसी ने इन्सान को पैदा किया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,4,'Ar-Rahmaan','عَلَّمَهُ ٱلۡبَيَانَ','اسی نے اس کو بولنا سکھایا','˹and˺ taught them speech','उसी ने उनको (अपना मतलब) बयान करना सिखाया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,5,'Ar-Rahmaan','ٱلشَّمۡسُ وَٱلۡقَمَرُ بِحُسۡبَانࣲ‏','سورج اور چاند ایک حساب مقرر سے چل رہے ہیں','The sun and the moon ˹travel˺ with precision','सूरज और चाँद एक मुक़र्रर हिसाब से चल रहे हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,6,'Ar-Rahmaan','وَٱلنَّجۡمُ وَٱلشَّجَرُ يَسۡجُدَانِ','اور بوٹیاں اور درخت سجدہ کر رہے ہیں','The stars and the trees bow down ˹in submission˺','और बूटियाँ बेलें, और दरख्त (उसी को) सजदा करते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,7,'Ar-Rahmaan','وَٱلسَّمَآءَ رَفَعَهَا وَوَضَعَ ٱلۡمِيزَانَ','اور اسی نے آسمان کو بلند کیا اور ترازو قائم کی','As for the sky, He raised it ˹high˺, and set the balance ˹of justice˺','और उसी ने आसमान बुलन्द किया और तराजू (इन्साफ) को क़ायम किया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,8,'Ar-Rahmaan','أَلَّا تَطۡغَوۡاْ فِي ٱلۡمِيزَانِ','کہ ترازو (سے تولنے) میں حد سے تجاوز نہ کرو','so that you do not defraud the scales','ताकि तुम लोग तराज़ू (से तौलने) में हद से तजाउज़ न करो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,9,'Ar-Rahmaan','وَأَقِيمُواْ ٱلۡوَزۡنَ بِٱلۡقِسۡطِ وَلَا تُخۡسِرُواْ ٱلۡمِيزَانَ','اور انصاف کے ساتھ ٹھیک تولو۔ اور تول کم مت کرو','Weigh with justice, and do not give short measure','और ईन्साफ के साथ ठीक तौलो और तौल कम न करो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,10,'Ar-Rahmaan','وَٱلۡأَرۡضَ وَضَعَهَا لِلۡأَنَامِ','اور اسی نے خلقت کے لئے زمین بچھائی','He laid out the earth for all beings','और उसी ने लोगों के नफे क़े लिए ज़मीन बनायी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,11,'Ar-Rahmaan','فِيهَا فَٰكِهَةࣱ وَٱلنَّخۡلُ ذَاتُ ٱلۡأَكۡمَامِ','اس میں میوے اور کھجور کے درخت ہیں جن کے خوشوں پر غلاف ہوتے ہیں','In it are fruit, palm trees with date stalks','कि उसमें मेवे और खजूर के दरख्त हैं जिसके ख़ोशों में ग़िलाफ़ होते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,12,'Ar-Rahmaan','وَٱلۡحَبُّ ذُو ٱلۡعَصۡفِ وَٱلرَّيۡحَانُ','اور اناج جس کے ساتھ بھس ہوتا ہے اور خوشبودار پھول','and grain with husks, and aromatic plants','और अनाज जिसके साथ भुस होता है और ख़ुशबूदार फूल');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,13,'Ar-Rahmaan','فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ','تو (اے گروہ جن وانس) تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟','Then which of your Lord’s favours will you ˹humans and jinn˺ both deny','तो (ऐ गिरोह जिन व इन्स) तुम दोनों अपने परवरदिगार की कौन कौन सी नेअमतों को न मानोगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,14,'Ar-Rahmaan','خَلَقَ ٱلۡإِنسَٰنَ مِن صَلۡصَٰلࣲ كَٱلۡفَخَّارِ','اسی نے انسان کو ٹھیکرے کی طرح کھنکھناتی مٹی سے بنایا','He created humankind from ˹sounding˺ clay like pottery','उसी ने इन्सान को ठीकरे की तरह खन खनाती हुई मिटटी से पैदा किया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,15,'Ar-Rahmaan','وَخَلَقَ ٱلۡجَآنَّ مِن مَّارِجࣲ مِّن نَّارࣲ‏','اور جنات کو آگ کے شعلے سے پیدا کیا','and created jinn from a ˹smokeless˺ flame of fire','और उसी ने जिन्नात को आग के शोले से पैदा किया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,16,'Ar-Rahmaan','فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ','تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟','Then which of your Lord’s favours will you both deny','तो (ऐ गिरोह जिन व इन्स) तुम अपने परवरदिगार की कौन कौन सी नेअमतों से मुकरोगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,17,'Ar-Rahmaan','رَبُّ ٱلۡمَشۡرِقَيۡنِ وَرَبُّ ٱلۡمَغۡرِبَيۡنِ','وہی دونوں مشرقوں اور دونوں مغربوں کا مالک (ہے)','˹He is˺ Lord of the two easts and the two wests','वही जाड़े गर्मी के दोनों मशरिकों का मालिक है और दोनों मग़रिबों का (भी) मालिक है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,18,'Ar-Rahmaan','فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ','تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟','Then which of your Lord’s favours will you both deny','तो (ऐ जिनों) और (आदमियों) तुम अपने परवरदिगार की किस किस नेअमत से इन्कार करोगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,19,'Ar-Rahmaan','مَرَجَ ٱلۡبَحۡرَيۡنِ يَلۡتَقِيَانِ','اسی نے دو دریا رواں کئے جو آپس میں ملتے ہیں','He merges the two bodies of ˹fresh and salt˺ water','उसी ने दरिया बहाए जो बाहम मिल जाते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,20,'Ar-Rahmaan','بَيۡنَهُمَا بَرۡزَخࣱ لَّا يَبۡغِيَانِ','دونوں میں ایک آڑ ہے کہ (اس سے) تجاوز نہیں کرسکتے','yet between them is a barrier they never cross','दो के दरमियान एक हद्दे फ़ासिल (आड़) है जिससे तजाउज़ नहीं कर सकते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,21,'Ar-Rahmaan','فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ','تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟','Then which of your Lord’s favours will you both deny','तो (ऐ जिन व इन्स) तुम दोनों अपने परवरदिगार की किस किस नेअमत को झुठलाओगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,22,'Ar-Rahmaan','يَخۡرُجُ مِنۡهُمَا ٱللُّؤۡلُؤُ وَٱلۡمَرۡجَانُ','دونوں دریاؤں سے موتی اور مونگے نکلتے ہیں','Out of both ˹waters˺ come forth pearls and coral','इन दोनों दरियाओं से मोती और मूँगे निकलते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,23,'Ar-Rahmaan','فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ','تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟','Then which of your Lord’s favours will you both deny','(तो जिन व इन्स) तुम दोनों अपने परवरदिगार की कौन कौन सी नेअमत को न मानोगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,24,'Ar-Rahmaan','وَلَهُ ٱلۡجَوَارِ ٱلۡمُنشَـَٔاتُ فِي ٱلۡبَحۡرِ كَٱلۡأَعۡلَٰمِ','اور جہاز بھی اسی کے ہیں جو دریا میں پہاڑوں کی طرح اونچے کھڑے ہوتے ہیں','To Him belong the ships with raised sails, sailing through the seas like mountains','और जहाज़ जो दरिया में पहाड़ों की तरह ऊँचे खड़े रहते हैं उसी के हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,25,'Ar-Rahmaan','فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ','تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟','Then which of your Lord’s favours will you both deny','तो (ऐ जिन व इन्स) तुम अपने परवरदिगार की किस किस नेअमत को झुठलाओगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,26,'Ar-Rahmaan','كُلُّ مَنۡ عَلَيۡهَا فَانࣲ‏','جو (مخلوق) زمین پر ہے سب کو فنا ہونا ہے','Every being on earth is bound to perish','जो (मख़लूक) ज़मीन पर है सब फ़ना होने वाली है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,27,'Ar-Rahmaan','وَيَبۡقَىٰ وَجۡهُ رَبِّكَ ذُو ٱلۡجَلَٰلِ وَٱلۡإِكۡرَامِ','اور تمہارے پروردگار ہی کی ذات (بابرکات) جو صاحب جلال وعظمت ہے باقی رہے گی','Only your Lord Himself, full of Majesty and Honour, will remain ˹forever˺','और सिर्फ तुम्हारे परवरदिगार की ज़ात जो अज़मत और करामत वाली है बाक़ी रहेगी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,28,'Ar-Rahmaan','فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ','تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟','Then which of your Lord’s favours will you both deny','तो तुम दोनों अपने मालिक की किस किस नेअमत से इन्कार करोगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,29,'Ar-Rahmaan','يَسۡـَٔلُهُۥ مَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ كُلَّ يَوۡمٍ هُوَ فِي شَأۡنࣲ‏','آسمان اور زمین میں جتنے لوگ ہیں سب اسی سے مانگتے ہیں۔ وہ ہر روز کام میں مصروف رہتا ہے','All those in the heavens and the earth are dependent on Him. Day in and day out He has something to bring about','और जितने लोग सारे आसमान व ज़मीन में हैं (सब) उसी से माँगते हैं वह हर रोज़ (हर वक्त) मख़लूक के एक न एक काम में है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,30,'Ar-Rahmaan','فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ','تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟','Then which of your Lord’s favours will you both deny','तो तुम दोनों अपने सरपरस्त की कौन कौन सी नेअमत से मुकरोगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,31,'Ar-Rahmaan','سَنَفۡرُغُ لَكُمۡ أَيُّهَ ٱلثَّقَلَانِ','اے دونوں جماعتو! ہم عنقریب تمہاری طرف متوجہ ہوتے ہیں','We will soon attend to you ˹for judgment˺, O two multitudes ˹of jinn and humans˺','(ऐ दोनों गिरोहों) हम अनक़रीब ही तुम्हारी तरफ मुतावज्जे होंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,32,'Ar-Rahmaan','فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ','تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟','Then which of your Lord’s favours will you both deny','तो तुम दोनों अपने पालने वाले की किस किस नेअमत को न मानोगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,33,'Ar-Rahmaan','يَٰمَعۡشَرَ ٱلۡجِنِّ وَٱلۡإِنسِ إِنِ ٱسۡتَطَعۡتُمۡ أَن تَنفُذُواْ مِنۡ أَقۡطَارِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ فَٱنفُذُواْۚ لَا تَنفُذُونَ إِلَّا بِسُلۡطَٰنࣲ‏','اے گروہِ جن وانس اگر تمہیں قدرت ہو کہ آسمان اور زمین کے کناروں سے نکل جاؤ تو نکل جاؤ۔ اور زور کے سوا تم نکل سکنے ہی کے نہیں','O assembly of jinn and humans! If you can penetrate beyond the realms of the heavens and the earth, then do so. ˹But˺ you cannot do that without ˹Our˺ authority','ऐ गिरोह जिन व इन्स अगर तुममें क़ुदरत है कि आसमानों और ज़मीन के किनारों से (होकर कहीं) निकल (कर मौत या अज़ाब से भाग) सको तो निकल जाओ (मगर) तुम तो बग़ैर क़ूवत और ग़लबे के निकल ही नहीं सकते (हालॉ कि तुममें न क़ूवत है और न ही ग़लबा)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,34,'Ar-Rahmaan','فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ','تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟','Then which of your Lord’s favours will you both deny','तो तुम अपने परवरदिगार की किस किस नेअमत को झुठलाओगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,35,'Ar-Rahmaan','يُرۡسَلُ عَلَيۡكُمَا شُوَاظࣱ مِّن نَّارࣲ وَنُحَاسࣱ فَلَا تَنتَصِرَانِ','تم پر آگ کے شعلے اور دھواں چھوڑ دیا جائے گا تو پھر تم مقابلہ نہ کرسکو گے','Flames of fire and ˹molten˺ copper will be sent against you, and you will not be able to defend one another','(गुनाहगार जिनों और आदमियों जहन्नुम में) तुम दोनो पर आग का सब्ज़ शोला और सियाह धुऑं छोड़ दिया जाएगा तो तुम दोनों (किस तरह) रोक नहीं सकोगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,36,'Ar-Rahmaan','فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ','تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟','Then which of your Lord’s favours will you both deny','फिर तुम दोनों अपने परवरदिगार की किस किस नेअमत से इन्कार करोगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,37,'Ar-Rahmaan','فَإِذَا ٱنشَقَّتِ ٱلسَّمَآءُ فَكَانَتۡ وَرۡدَةࣰ كَٱلدِّهَانِ','پھر جب آسمان پھٹ کر تیل کی تلچھٹ کی طرح گلابی ہوجائے گا (تو) وہ کیسا ہولناک دن ہوگا','˹How horrible will it be˺ when the heavens will split apart, becoming rose-red like ˹burnt˺ oil','फिर जब आसमान फट कर (क़यामत में) तेल की तरह लाल हो जाऐगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,38,'Ar-Rahmaan','فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ','تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟','Then which of your Lord’s favours will you both deny','तो तुम दोनों अपने परवरदिगार की किस किस नेअमत से मुकरोगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,39,'Ar-Rahmaan','فَيَوۡمَئِذࣲ لَّا يُسۡـَٔلُ عَن ذَنۢبِهِۦٓ إِنسࣱ وَلَا جَآنࣱّ‏','اس روز نہ تو کسی انسان سے اس کے گناہوں کے بارے میں پرسش کی جائے گی اور نہ کسی جن سے','On that Day there will be no need for any human or jinn to be asked about their sins','तो उस दिन न तो किसी इन्सान से उसके गुनाह के बारे में पूछा जाएगा न किसी जिन से');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,40,'Ar-Rahmaan','فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ','تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟','Then which of your Lord’s favours will you both deny','तो तुम दोनों अपने मालिक की किस किस नेअमत को न मानोगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,41,'Ar-Rahmaan','يُعۡرَفُ ٱلۡمُجۡرِمُونَ بِسِيمَٰهُمۡ فَيُؤۡخَذُ بِٱلنَّوَٰصِي وَٱلۡأَقۡدَامِ','گنہگار اپنے چہرے ہی سے پہچان لئے جائیں گے تو پیشانی کے بالوں اور پاؤں سے پکڑ لئے جائیں گے','The wicked will be recognized by their appearance, then will be seized by ˹their˺ forelocks and feet','गुनाहगार लोग तो अपने चेहरों ही से पहचान लिए जाएँगे तो पेशानी के पटटे और पाँव पकड़े (जहन्नुम में डाल दिये जाएँगे)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,42,'Ar-Rahmaan','فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ','تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟','Then which of your Lord’s favours will you both deny','आख़िर तुम दोनों अपने परवरदिगार की किस किस नेअमत से इन्कार करोगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,43,'Ar-Rahmaan','هَٰذِهِۦ جَهَنَّمُ ٱلَّتِي يُكَذِّبُ بِهَا ٱلۡمُجۡرِمُونَ','یہی وہ جہنم ہے جسے گنہگار لوگ جھٹلاتے تھے','˹They will be told,˺ “This is the Hell which the wicked denied.”','(फिर उनसे कहा जाएगा) यही वह जहन्नुम है जिसे गुनाहगार लोग झुठलाया करते थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,44,'Ar-Rahmaan','يَطُوفُونَ بَيۡنَهَا وَبَيۡنَ حَمِيمٍ ءَانࣲ‏','وہ دوزخ اور کھولتے ہوئے گرم پانی کے درمیان گھومتے پھریں گے','They will alternate between its flames and scalding water','ये लोग दोज़ख़ और हद दरजा खौलते हुए पानी के दरमियान (बेक़रार दौड़ते) चक्कर लगाते फिरेंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,45,'Ar-Rahmaan','فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ','تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟','Then which of your Lord’s favours will you both deny','तो तुम दोनों अपने परवरदिगार की किस किस नेअमत को न मानोगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,46,'Ar-Rahmaan','وَلِمَنۡ خَافَ مَقَامَ رَبِّهِۦ جَنَّتَانِ','اور جو شخص اپنے پروردگار کے سامنے کھڑے ہونے سے ڈرا اس کے لئے دو باغ ہیں','And whoever is in awe of standing before their Lord will have two Gardens','और जो शख्स अपने परवरदिगार के सामने खड़े होने से डरता रहा उसके लिए दो दो बाग़ हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,47,'Ar-Rahmaan','فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ','تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟','Then which of your Lord’s favours will you both deny','तो तुम दोनों अपने परवरदिगार की कौन कौन सी नेअमत से इन्कार करोगे');
